// ===== Toulouse Way – bibliothèque commune (emails, pages, utilitaires) =====
const TW = (() => {
  const DEFAULTS = {
    nom_asso: 'Toulouse Way', slogan: 'Mieux vivre ici, ensemble',
    couleur_principale: '#F26716', couleur_encre: '#12343B',
    logo_url: 'https://www.toulouseway.org/assets/logo.png', site_url: 'https://www.toulouseway.org',
    email_gestionnaire: 'contact@toulouseway.org', n8n_url: '', signature: "L'équipe Toulouse Way",
    pied_de_page: 'Toulouse Way · Association loi 1901 · Toulouse',
    score_minimum: '50', max_propositions: '3'
  };
  const RTL = ['ar', 'fa', 'he', 'ur'];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const list = s => String(s ?? '').split(/[,;]/).map(x => x.trim()).filter(Boolean);
  const norm = s => String(s ?? '').trim().toLowerCase();
  const rnd = n => { const a = 'abcdefghijkmnpqrstuvwxyz23456789'; let s = ''; for (let i = 0; i < n; i++) s += a[Math.floor(Math.random() * a.length)]; return s; };
  const uid = p => `${p}-${Date.now().toString(36).toUpperCase()}${rnd(3).toUpperCase()}`;
  const token = () => rnd(32);

  function params(rows) {
    const P = { ...DEFAULTS };
    for (const r of rows || []) if (r && r.id && String(r.valeur ?? '').trim() !== '') P[String(r.id).trim()] = String(r.valeur).trim();
    P.n8n_url = String(P.n8n_url).replace(/\/+$/, '');
    return P;
  }
  const link = (P, path, q) => `${P.n8n_url}/webhook/${path}` + (q ? '?' + Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&') : '');

  // ---------- Dates (texte « AAAA-MM-JJ », JJ/MM/AAAA ou numéro de série Sheets) ----------
  function isoDate(v) {
    if (v === null || v === undefined || v === '') return '';
    if (typeof v === 'number') { const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return d.toISOString().slice(0, 10); }
    const s = String(v).trim(); let m;
    if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
    if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
    return '';
  }
  const todayParis = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const nowParis = () => todayParis() + ' ' + new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' }).format(new Date());
  const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 864e5);
  function longDate(iso, lang) {
    if (!iso) return '';
    const d = new Date(iso + 'T12:00:00Z');
    try { return new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : (lang || 'fr') , { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(d); }
    catch (e) { return iso; }
  }

  // ---------- Couleurs ----------
  function mix(hex, other, t) {
    const h = x => x.replace('#', '').padEnd(6, '0'); const a = h(hex), b = h(other);
    return '#' + [0, 2, 4].map(i => Math.round(parseInt(a.substr(i, 2), 16) * (1 - t) + parseInt(b.substr(i, 2), 16) * t).toString(16).padStart(2, '0')).join('');
  }

  // ---------- Rendu d'un texte de template ----------
  // {{variable}} = valeur (échappée) · **gras** · [[Texte du bouton|variable_lien]] = bouton
  // Un bloc qui ne contient que {{details_...}} ou {{liste_...}} insère un encadré HTML.
  function button(P, label, url, quiet) {
    const c = P.couleur_principale;
    const style = quiet
      ? `display:inline-block;padding:11px 20px;margin:4px 8px 4px 0;border:2px solid ${c};color:${mix(c, '#000000', 0.25)};background:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`
      : `display:inline-block;padding:13px 22px;margin:4px 8px 4px 0;background:${c};color:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`;
    return `<a href="${esc(url)}" style="${style}">${esc(label)}</a>`;
  }
  function renderText(text, vars, P) {
    const html = {}; for (const k in vars) if (/^(details_|liste_)/.test(k)) html[k] = true;
    const blocks = String(text ?? '').replace(/\r/g, '').split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);
    let nb = 0;
    return blocks.map(b => {
      const only = b.match(/^\{\{(\w+)\}\}$/);
      if (only && html[only[1]]) return vars[only[1]] || '';
      const buttonsOnly = /^(\s*\[\[[^\]]+\]\]\s*)+$/.test(b);
      let out = '', last = 0;
      const re = /\{\{(\w+)\}\}|\[\[([^\]|]+)\|(\w+)\]\]|\*\*(.+?)\*\*/g; let m;
      while ((m = re.exec(b))) {
        out += esc(b.slice(last, m.index)).replace(/\n/g, '<br>');
        if (m[1]) out += html[m[1]] ? (vars[m[1]] || '') : esc(vars[m[1]] ?? '');
        else if (m[2]) out += button(P, m[2].trim(), vars[m[3]] || '#', nb++ > 0);
        else out += '<strong>' + esc(m[4]).replace(/\{\{(\w+)\}\}/g, (_, k) => html[k] ? '' : esc(vars[k] ?? '')) + '</strong>';
        last = re.lastIndex;
      }
      out += esc(b.slice(last)).replace(/\n/g, '<br>');
      return buttonsOnly ? `<p style="margin:22px 0">${out}</p>` : `<p style="margin:0 0 16px">${out}</p>`;
    }).join('\n');
  }
  const fill = (text, vars) => String(text ?? '').replace(/\{\{(\w+)\}\}/g, (_, k) => /^(details_|liste_)/.test(k) ? '' : String(vars[k] ?? ''));

  // ---------- Choix des templates selon les langues ----------
  function pick(templates, cle, langs) {
    const rows = (templates || []).filter(t => norm(t.cle) === norm(cle) && String(t.contenu || '').trim());
    const by = {}; for (const t of rows) by[norm(t.langue)] = t;
    const found = []; for (const l of (langs || []).map(norm)) if (by[l] && !found.includes(by[l])) found.push(by[l]);
    if (!found.length) for (const l of ['fr', 'en']) if (by[l]) { found.push(by[l]); break; }
    if (!found.length && rows[0]) found.push(rows[0]);
    return found;
  }

  // ---------- Mise en page des emails ----------
  function layout(P, sections, preheader) {
    const c = P.couleur_principale, ink = P.couleur_encre;
    const body = sections.map((s, i) => {
      const rtl = RTL.includes(norm(s.lang));
      return `${i ? `<tr><td style="padding:0 36px"><div style="border-top:1px dashed ${mix(c, '#ffffff', 0.55)};margin:8px 0 0"></div></td></tr>` : ''}
<tr><td dir="${rtl ? 'rtl' : 'ltr'}" lang="${esc(s.lang)}" style="padding:28px 36px 12px;text-align:${rtl ? 'right' : 'left'};font-family:'Atkinson Hyperlegible',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:${ink}">${s.html}</td></tr>`;
    }).join('');
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(P.nom_asso)}</title></head>
<body style="margin:0;padding:0;background:#EEF2F2">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader || '')}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F2;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden">
<tr><td style="padding:22px 36px 18px;border-bottom:4px solid ${c}">
  <a href="${esc(P.site_url)}" style="text-decoration:none"><img src="${esc(P.logo_url)}" alt="${esc(P.nom_asso)}" height="44" style="height:44px;max-width:220px;display:block;border:0"></a>
</td></tr>
${body}
<tr><td style="padding:12px 36px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:${ink}">${esc(P.signature)}</td></tr>
<tr><td style="background:${ink};padding:20px 36px;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:1.5;color:#D8E3E4">
  <div style="color:#ffffff;font-weight:700;font-size:15px">${esc(P.slogan)}</div>
  <div style="margin-top:6px">${esc(P.pied_de_page)}</div>
  <div style="margin-top:6px"><a href="${esc(P.site_url)}" style="color:${mix(c, '#ffffff', 0.35)}">${esc(String(P.site_url).replace(/^https?:\/\//, ''))}</a></div>
</td></tr></table></td></tr></table></body></html>`;
  }

  // Construit un email {sujet, html} à partir d'une clé de template et d'une liste de langues
  function email(templates, cle, langs, vars, P) {
    const rows = pick(templates, cle, langs);
    if (!rows.length) throw new Error(`Template introuvable : ${cle}`);
    const sujets = [...new Set(rows.map(t => fill(t.sujet, vars).trim()).filter(Boolean))];
    const sections = rows.map(t => ({ lang: norm(t.langue), html: renderText(t.contenu, vars, P) }));
    return { sujet: sujets.slice(0, 2).join(' / '), html: layout(P, sections, fill(rows[0].sujet, vars)), langues: rows.map(t => norm(t.langue)) };
  }

  // ---------- Encadrés ----------
  function box(P, inner) {
    return `<div style="background:${mix(P.couleur_principale, '#ffffff', 0.9)};border-left:4px solid ${P.couleur_principale};border-radius:10px;padding:16px 18px;margin:6px 0 20px">${inner}</div>`;
  }
  const L = {
    fr: { date: 'Date', heure: 'Horaire', lieu: 'Lieu', lien: 'En ligne', intervenant: 'Animé par', type: 'Type', metiers: 'Métiers recherchés', langues: 'Langues', ville: 'Ville', parcours: 'Parcours', email: 'Email', tel: 'Téléphone' },
    en: { date: 'Date', heure: 'Time', lieu: 'Venue', lien: 'Online', intervenant: 'Led by', type: 'Type', metiers: 'Target jobs', langues: 'Languages', ville: 'City', parcours: 'Background', email: 'Email', tel: 'Phone' }
  };
  const lab = lang => L[norm(lang)] || L.fr;
  function rowsTable(rows) {
    return '<table role="presentation" cellpadding="0" cellspacing="0" style="font-size:15px;line-height:1.5">' +
      rows.filter(r => r[1]).map(([k, v]) => `<tr><td style="padding:3px 16px 3px 0;color:#4A6266;vertical-align:top;white-space:nowrap">${esc(k)}</td><td style="padding:3px 0;vertical-align:top">${v}</td></tr>`).join('') + '</table>';
  }
  function sessionTitle(s, lang) { return (norm(lang) === 'en' && s.titre_en) ? s.titre_en : (s.titre || ''); }
  function detailsSession(P, s, lang) {
    const l = lab(lang), iso = isoDate(s.date);
    const h = s.heure_debut ? (s.heure_fin ? `${s.heure_debut} – ${s.heure_fin}` : s.heure_debut) : '';
    return box(P, `<div style="font-size:18px;font-weight:700;margin-bottom:8px">${esc(sessionTitle(s, lang))}</div>` + rowsTable([
      [l.date, esc(longDate(iso, lang))], [l.heure, esc(h)], [l.lieu, esc(s.lieu)],
      [l.lien, s.lien_visio ? `<a href="${esc(s.lien_visio)}" style="color:${P.couleur_principale}">${esc(s.lien_visio)}</a>` : ''],
      [l.intervenant, esc(s.intervenant)]
    ]) + (s.infos_pratiques ? `<div style="margin-top:10px">${esc(s.infos_pratiques)}</div>` : ''));
  }
  // Coordonnées d'un contact : sans libellés, donc lisible dans toutes les langues
  function detailsContact(P, c) {
    const lines = [
      `<div style="font-size:18px;font-weight:700">${esc(`${c.prenom || ''} ${c.nom || ''}`.trim())}</div>`,
      [c.poste, c.entreprise].filter(Boolean).length ? `<div>${esc([c.poste, c.entreprise].filter(Boolean).join(' · '))}</div>` : '',
      c.email ? `<div>✉️ <a dir="ltr" href="mailto:${esc(c.email)}" style="color:${P.couleur_principale};unicode-bidi:isolate">${esc(c.email)}</a></div>` : '',
      c.telephone ? `<div>📞 <a dir="ltr" href="tel:${esc(String(c.telephone).replace(/\s/g, ''))}" style="color:${P.couleur_principale};unicode-bidi:isolate">${esc(c.telephone)}</a></div>` : '',
      c.ville ? `<div>📍 ${esc(c.ville)}</div>` : ''
    ];
    return box(P, lines.join(''));
  }
  function libelles(listes, type, codes, lang) {
    const m = {}; for (const r of listes || []) if (norm(r.type) === type) m[norm(r.code)] = (norm(lang) === 'en' && r.libelle_en) ? r.libelle_en : (r.libelle_fr || r.code);
    return list(codes).map(c => m[norm(c)] || c).join(', ');
  }
  function detailsDemandeur(P, d, lang, listes, withContact) {
    const l = lab(lang);
    return box(P, `<div style="font-size:18px;font-weight:700;margin-bottom:8px">${esc(`${d.prenom || ''} ${d.nom || ''}`.trim())}</div>` + rowsTable([
      [l.metiers, esc(libelles(listes, 'metier', d.metiers, lang))], [l.langues, esc(libelles(listes, 'langue', d.langues, lang))],
      [l.ville, esc(d.ville)], [l.parcours, esc(d.parcours)],
      [l.email, withContact && d.email ? `<a href="mailto:${esc(d.email)}" style="color:${P.couleur_principale}">${esc(d.email)}</a>` : ''],
      [l.tel, withContact ? esc(d.telephone) : '']
    ]));
  }

  // ---------- Page de réponse (après un clic dans un email) ----------
  function page(P, o) {
    const c = P.couleur_principale, ink = P.couleur_encre;
    const tone = { ok: '#2E7D5B', warn: '#B7791F', err: '#B23A2E' }[o.tone || 'ok'];
    const rtl = RTL.includes(norm(o.lang));
    return `<!doctype html><html lang="${esc(o.lang || 'fr')}" dir="${rtl ? 'rtl' : 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(o.title)} – ${esc(P.nom_asso)}</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&display=swap" rel="stylesheet">
<style>body{margin:0;min-height:100vh;display:flex;flex-direction:column;background:#EEF2F2;font-family:'Atkinson Hyperlegible',Arial,sans-serif;color:${ink}}
header{padding:18px 24px;background:#fff;border-bottom:4px solid ${c}}header img{height:40px}
main{flex:1;display:flex;align-items:center;justify-content:center;padding:32px 16px}
.card{background:#fff;border-radius:18px;max-width:520px;width:100%;padding:36px 32px;box-shadow:0 1px 0 rgba(18,52,59,.06),0 12px 32px -18px rgba(18,52,59,.35)}
.mark{width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:${tone}1A;color:${tone};font-size:26px;font-weight:700}
h1{font-family:'Bricolage Grotesque',Arial,sans-serif;font-weight:800;font-size:28px;line-height:1.15;margin:18px 0 10px}
p{font-size:17px;line-height:1.6;margin:0 0 12px}a.btn{display:inline-block;margin-top:10px;padding:12px 20px;border-radius:999px;background:${c};color:#fff;text-decoration:none;font-weight:700}
footer{padding:18px;text-align:center;font-size:14px;color:#4A6266}</style></head>
<body><header><a href="${esc(P.site_url)}"><img src="${esc(P.logo_url)}" alt="${esc(P.nom_asso)}"></a></header>
<main><div class="card"><div class="mark">${o.tone === 'err' ? '!' : o.tone === 'warn' ? 'i' : '✓'}</div><h1>${esc(o.title)}</h1>${(o.paras || []).map(p => `<p>${esc(p)}</p>`).join('')}${o.cta ? `<a class="btn" href="${esc(o.cta.url)}">${esc(o.cta.label)}</a>` : ''}</div></main>
<footer>${esc(P.slogan)} · ${esc(P.nom_asso)}</footer></body></html>`;
  }

  return { DEFAULTS, RTL, esc, list, norm, uid, token, params, link, isoDate, todayParis, nowParis, daysBetween, longDate, mix,
    renderText, fill, pick, layout, email, button, box, detailsSession, detailsContact, detailsDemandeur, libelles, sessionTitle, page };
})();

const TPL = "<!doctype html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Demande de mise en relation – Toulouse Way</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:ital,wght@0,400;0,700;1,400&family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700;12..96,800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --orange:#F26716; --orange-ink:#B4470A; --orange-soft:#FDEBDD;\n  --ink:#12343B; --ink-2:#2B4D54; --muted:#4A6266; --line:#D5DFE0; --mist:#EEF2F2; --paper:#FFFFFF;\n  --brique:#F6DCCD; --ok:#2E7D5B; --ok-soft:#E3F2EA; --warn:#9A6212; --warn-soft:#FBF0DC; --err:#B23A2E; --err-soft:#FBE6E3;\n  --s-confirme:#00897B; --s-attente:#F26716; --s-annule:#B9C4C6;\n  --r-sm:8px; --r-md:12px; --r-lg:18px;\n  --f-display:'Bricolage Grotesque','Atkinson Hyperlegible',system-ui,sans-serif;\n  --f-body:'Atkinson Hyperlegible','Noto Sans Arabic',system-ui,-apple-system,'Segoe UI',sans-serif;\n  --shadow:0 1px 0 rgba(18,52,59,.05),0 14px 34px -22px rgba(18,52,59,.45);\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;overflow-x:hidden}\nimg,svg,iframe,video{max-width:100%}\ncode,a{overflow-wrap:anywhere}\ninput,select,textarea{max-width:100%}\nbody{margin:0;font-family:var(--f-body);font-size:16px;line-height:1.55;color:var(--ink);background:var(--mist)}\n[dir=rtl] body{font-family:'Noto Sans Arabic',var(--f-body)}\nh1,h2,h3{font-family:var(--f-display);line-height:1.15;margin:0;letter-spacing:-.01em}\na{color:var(--orange-ink)}\nbutton,input,select,textarea{font:inherit;color:inherit}\n:focus-visible{outline:3px solid var(--orange);outline-offset:2px;border-radius:4px}\n.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}\n@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n\n/* Boutons */\n.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:2px solid transparent;border-radius:999px;padding:11px 22px;font-weight:700;cursor:pointer;text-decoration:none;line-height:1.2;transition:background .15s,border-color .15s}\n.btn-primary{background:var(--orange);color:#fff}\n.btn-primary:hover{background:var(--orange-ink)}\n.btn-ghost{background:transparent;border-color:var(--line);color:var(--ink)}\n.btn-ghost:hover{border-color:var(--ink)}\n.btn-danger{background:transparent;border-color:var(--err-soft);color:var(--err)}\n.btn-danger:hover{border-color:var(--err)}\n.btn-sm{padding:6px 14px;font-size:14px}\n.btn[disabled]{opacity:.55;cursor:not-allowed}\n\n/* Champs */\n.field{display:flex;flex-direction:column;gap:6px;margin-bottom:18px;min-width:0}\n.field label,.field .label{font-weight:700;font-size:15px}\n.field .hint{font-size:14px;color:var(--muted);margin-top:-2px}\n.req{color:var(--orange-ink)}\n.input,.select,.textarea{width:100%;border:1.5px solid var(--line);border-radius:var(--r-sm);padding:11px 13px;background:#fff;min-height:46px}\n.textarea{min-height:110px;resize:vertical}\n.input:focus,.select:focus,.textarea:focus{border-color:var(--ink);outline:none;box-shadow:0 0 0 3px var(--orange-soft)}\n.field.invalid .input,.field.invalid .ms-trigger,.field.invalid .textarea{border-color:var(--err)}\n.err-msg{color:var(--err);font-size:14px;display:none}\n.field.invalid .err-msg{display:block}\n.field label.check,.check{display:flex;gap:10px;align-items:flex-start;font-size:15px;font-weight:400}\n.check input{width:20px;height:20px;margin-top:2px;accent-color:var(--orange);flex:none}\n.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}\n@media (max-width:640px){.grid-2{grid-template-columns:1fr}}\n\n/* Multi-sélection */\n.ms{position:relative}\n.ms-trigger{width:100%;min-height:46px;border:1.5px solid var(--line);border-radius:var(--r-sm);background:#fff;padding:7px 40px 7px 9px;display:flex;flex-wrap:wrap;gap:6px;align-items:center;text-align:start;cursor:pointer;position:relative}\n.ms-trigger::after{content:\"\";position:absolute;inset-inline-end:16px;top:50%;width:8px;height:8px;border-right:2px solid var(--ink);border-bottom:2px solid var(--ink);transform:translateY(-70%) rotate(45deg)}\n.ms[aria-expanded=true] .ms-trigger{border-color:var(--ink);box-shadow:0 0 0 3px var(--orange-soft)}\n.ms-placeholder{color:var(--muted);padding:3px 4px}\n.chip{display:inline-flex;align-items:center;gap:4px;background:var(--orange-soft);color:var(--ink);border-radius:999px;padding:3px 6px 3px 11px;font-size:14px;font-weight:700}\n.chip button{border:0;background:transparent;width:22px;height:22px;border-radius:50%;cursor:pointer;line-height:1;font-size:16px;color:var(--orange-ink)}\n.chip button:hover{background:#fff}\n.ms-panel{position:absolute;z-index:30;inset-inline:0;top:calc(100% + 6px);background:#fff;border:1.5px solid var(--ink);border-radius:var(--r-md);box-shadow:var(--shadow);display:none;overflow:hidden}\n.ms[aria-expanded=true] .ms-panel{display:block}\n.ms-search{border:0;border-bottom:1px solid var(--line);width:100%;padding:12px 14px;outline:none}\n.ms-list{max-height:280px;overflow:auto;padding:6px 0;margin:0;list-style:none}\n.ms-group{font-size:13px;font-weight:700;color:var(--muted);padding:10px 14px 4px}\n.ms-opt{display:flex;align-items:center;gap:10px;padding:8px 14px;cursor:pointer}\n.ms-opt:hover,.ms-opt.active{background:var(--mist)}\n.ms-opt input{width:18px;height:18px;accent-color:var(--orange);pointer-events:none}\n.ms-opt .natif{color:var(--muted);font-size:14px;margin-inline-start:auto}\n.ms-empty{padding:12px 14px;color:var(--muted)}\n\n/* Badges de statut */\n.badge{display:inline-flex;align-items:center;gap:6px;padding:2px 10px;border-radius:999px;font-size:13px;font-weight:700;white-space:nowrap;background:var(--mist);color:var(--ink-2)}\n.badge::before{content:\"\";width:7px;height:7px;border-radius:50%;background:currentColor}\n.b-ok{background:var(--ok-soft);color:var(--ok)} .b-warn{background:var(--warn-soft);color:var(--warn)}\n.b-err{background:var(--err-soft);color:var(--err)} .b-new{background:var(--orange-soft);color:var(--orange-ink)} .b-off{background:var(--mist);color:var(--muted)}\n\n/* Toast */\n.toast{position:fixed;inset-inline:16px;bottom:20px;margin:auto;max-width:440px;background:var(--ink);color:#fff;padding:13px 18px;border-radius:var(--r-md);box-shadow:var(--shadow);z-index:100;transform:translateY(16px);opacity:0;visibility:hidden;transition:transform .2s,opacity .2s,visibility 0s .2s}\n.toast.show{transform:none;opacity:1;visibility:visible;transition:transform .2s,opacity .2s}\n.toast.err{background:var(--err)}\n\n.hero{background:var(--ink);color:#fff;padding:0 20px 120px;position:relative;overflow:hidden}\n.topbar{max-width:880px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:18px 0}\n.logo{display:inline-flex;background:#fff;border-radius:12px;padding:8px 12px}\n.logo img{height:36px;display:block}\n.lang{display:flex;border:1.5px solid rgba(255,255,255,.35);border-radius:999px;overflow:hidden}\n.lang a{color:#fff;text-decoration:none;padding:6px 14px;font-weight:700;font-size:14px}\n.lang a[aria-current=true]{background:#fff;color:var(--ink)}\n.hero-in{max-width:880px;margin:0 auto;padding-top:40px;position:relative;z-index:1}\n.hero h1{font-size:clamp(34px,6vw,58px);font-weight:800;max-width:15ch}\n.hero p{font-size:19px;max-width:52ch;color:#D8E3E4;margin:18px 0 0}\n.path{position:absolute;inset-inline:0;bottom:24px;width:100%;height:120px;pointer-events:none}\nmain{max-width:880px;margin:-84px auto 0;padding:0 16px 48px;position:relative;z-index:2}\n.sheet{background:#fff;border-radius:var(--r-lg);box-shadow:var(--shadow);padding:34px clamp(20px,4vw,44px)}\nfieldset{border:0;margin:0 0 10px;padding:0}\nlegend{font-family:var(--f-display);font-weight:700;font-size:22px;margin-bottom:6px;padding:0;float:left;width:100%}\nlegend+*{clear:both}\n.legend-hint{color:var(--muted);margin:0 0 20px}\n.section+.section{border-top:1px solid var(--line);padding-top:26px;margin-top:8px}\n.actions{display:flex;flex-wrap:wrap;gap:16px;align-items:center;margin-top:10px}\n.actions .note{color:var(--muted);font-size:14px}\n.done{text-align:center;padding:20px 0}\n.done .mark{width:64px;height:64px;border-radius:50%;background:var(--ok-soft);color:var(--ok);display:flex;align-items:center;justify-content:center;font-size:32px;margin:0 auto 16px}\n.done h2{font-size:30px;margin-bottom:10px}\n.done p{max-width:46ch;margin:0 auto 10px;color:var(--ink-2)}\n.alert{background:var(--err-soft);color:var(--err);border-radius:var(--r-sm);padding:12px 14px;margin-bottom:16px;display:none}\nfooter{text-align:center;color:var(--muted);font-size:14px;padding:0 16px 32px}\n</style>\n</head>\n<body>\n<header class=\"hero\">\n  <div class=\"topbar\">\n    <a class=\"logo\" id=\"logo-link\"><img id=\"logo\" alt=\"\"></a>\n    <nav class=\"lang\" aria-label=\"Langue / Language\"><a href=\"?lang=fr\" data-l=\"fr\">FR</a><a href=\"?lang=en\" data-l=\"en\">EN</a></nav>\n  </div>\n  <div class=\"hero-in\">\n    <h1 data-t=\"title\"></h1>\n    <p data-t=\"intro\"></p>\n  </div>\n  <svg class=\"path\" viewBox=\"0 0 1200 120\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><path d=\"M-10 92 C 180 30, 320 118, 520 70 S 860 10, 1030 58 S 1180 96, 1215 60\" fill=\"none\" stroke=\"var(--orange)\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-dasharray=\"1 14\"/></svg>\n</header>\n<main>\n  <div class=\"sheet\" id=\"sheet\">\n    <form id=\"f\" novalidate>\n      <div class=\"alert\" id=\"alert\" role=\"alert\"></div>\n      <fieldset class=\"section\">\n        <legend data-t=\"s1\"></legend>\n        <p class=\"legend-hint\" data-t=\"s1h\"></p>\n        <div class=\"grid-2\">\n          <div class=\"field\"><label for=\"prenom\"><span data-t=\"prenom\"></span> <span class=\"req\">*</span></label><input class=\"input\" id=\"prenom\" name=\"prenom\" autocomplete=\"given-name\" required maxlength=\"80\"><span class=\"err-msg\" data-t=\"required\"></span></div>\n          <div class=\"field\"><label for=\"nom\"><span data-t=\"nom\"></span> <span class=\"req\">*</span></label><input class=\"input\" id=\"nom\" name=\"nom\" autocomplete=\"family-name\" required maxlength=\"80\"><span class=\"err-msg\" data-t=\"required\"></span></div>\n          <div class=\"field\"><label for=\"email\"><span data-t=\"email\"></span> <span class=\"req\">*</span></label><input class=\"input\" id=\"email\" name=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"120\"><span class=\"err-msg\" data-t=\"emailErr\"></span></div>\n          <div class=\"field\"><label for=\"telephone\" data-t=\"tel\"></label><input class=\"input\" id=\"telephone\" name=\"telephone\" type=\"tel\" autocomplete=\"tel\" maxlength=\"30\"></div>\n          <div class=\"field\"><label for=\"ville\" data-t=\"ville\"></label><input class=\"input\" id=\"ville\" name=\"ville\" autocomplete=\"address-level2\" maxlength=\"80\"></div>\n        </div>\n      </fieldset>\n      <fieldset class=\"section\">\n        <legend data-t=\"s2\"></legend>\n        <p class=\"legend-hint\" data-t=\"s2h\"></p>\n        <div class=\"field\" id=\"f-langues\"><span class=\"label\" id=\"l-langues\"><span data-t=\"langues\"></span> <span class=\"req\">*</span></span><span class=\"hint\" data-t=\"languesH\"></span><div id=\"ms-langues\"></div><span class=\"err-msg\" data-t=\"chooseOne\"></span></div>\n        <div class=\"field\" id=\"f-metiers\"><span class=\"label\" id=\"l-metiers\"><span data-t=\"metiers\"></span> <span class=\"req\">*</span></span><span class=\"hint\" data-t=\"metiersH\"></span><div id=\"ms-metiers\"></div><span class=\"err-msg\" data-t=\"chooseOne\"></span></div>\n        <div class=\"field\"><label for=\"parcours\" data-t=\"parcours\"></label><span class=\"hint\" data-t=\"parcoursH\"></span><textarea class=\"textarea\" id=\"parcours\" name=\"parcours\" maxlength=\"800\"></textarea></div>\n      </fieldset>\n      <div class=\"section\">\n        <div class=\"field\" id=\"f-rgpd\"><label class=\"check\"><input type=\"checkbox\" id=\"rgpd\" required><span data-t=\"rgpd\"></span></label><span class=\"err-msg\" data-t=\"rgpdErr\"></span></div>\n        <div class=\"actions\"><button class=\"btn btn-primary\" type=\"submit\" id=\"send\" data-t=\"send\"></button><span class=\"note\" data-t=\"note\"></span></div>\n      </div>\n    </form>\n  </div>\n</main>\n<footer id=\"foot\"></footer>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n<script>// Liste déroulante à choix multiples (accessible au clavier)\nfunction MultiSelect(root, opts) {\n  let selected = [];\n  let active = -1;\n  const o = Object.assign({ placeholder: 'Choisir…', search: 'Rechercher…', empty: 'Aucun résultat', remove: 'Retirer', max: 0 }, opts);\n  const uidN = 'ms' + Math.random().toString(36).slice(2, 8);\n  root.classList.add('ms'); root.setAttribute('aria-expanded', 'false');\n  root.innerHTML = `<div class=\"ms-trigger\" role=\"combobox\" tabindex=\"0\" aria-haspopup=\"listbox\" aria-controls=\"${uidN}-list\" ${o.labelledby ? `aria-labelledby=\"${o.labelledby}\"` : ''}></div>\n    <div class=\"ms-panel\"><input class=\"ms-search\" type=\"search\" autocomplete=\"off\" placeholder=\"${o.search}\" aria-label=\"${o.search}\"><ul class=\"ms-list\" id=\"${uidN}-list\" role=\"listbox\" aria-multiselectable=\"true\"></ul></div>`;\n  const trigger = root.querySelector('.ms-trigger'), panel = root.querySelector('.ms-panel');\n  const search = root.querySelector('.ms-search'), listEl = root.querySelector('.ms-list');\n  const esc = s => String(s ?? '').replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n  const label = v => (o.options.find(x => x.value === v) || { label: v }).label;\n\n  function renderTrigger() {\n    trigger.innerHTML = selected.length\n      ? selected.map(v => `<span class=\"chip\">${esc(label(v))}<button type=\"button\" data-rm=\"${esc(v)}\" aria-label=\"${esc(o.remove)} ${esc(label(v))}\">×</button></span>`).join('')\n      : `<span class=\"ms-placeholder\">${esc(o.placeholder)}</span>`;\n  }\n  function visible() {\n    const q = search.value.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\n    return o.options.filter(x => !q || (x.label + ' ' + (x.natif || '') + ' ' + (x.group || '')).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').includes(q));\n  }\n  function renderList() {\n    const items = visible(); let html = '', g = null;\n    items.forEach((x, i) => {\n      if (x.group && x.group !== g) { g = x.group; html += `<li class=\"ms-group\" role=\"presentation\">${esc(g)}</li>`; }\n      const on = selected.includes(x.value);\n      html += `<li class=\"ms-opt${i === active ? ' active' : ''}\" role=\"option\" id=\"${uidN}-${i}\" aria-selected=\"${on}\" data-v=\"${esc(x.value)}\"><input type=\"checkbox\" tabindex=\"-1\" ${on ? 'checked' : ''}><span>${esc(x.label)}</span>${x.natif && x.natif !== x.label ? `<span class=\"natif\" lang=\"${esc(x.value)}\">${esc(x.natif)}</span>` : ''}</li>`;\n    });\n    listEl.innerHTML = html || `<li class=\"ms-empty\">${esc(o.empty)}</li>`;\n    if (active >= 0) { trigger.setAttribute('aria-activedescendant', `${uidN}-${active}`); const el = document.getElementById(`${uidN}-${active}`); el && el.scrollIntoView({ block: 'nearest' }); }\n  }\n  function toggle(v) {\n    if (selected.includes(v)) selected = selected.filter(x => x !== v);\n    else { if (o.max && selected.length >= o.max) return; selected.push(v); }\n    renderTrigger(); renderList(); o.onChange && o.onChange(selected.slice());\n  }\n  function open(focusSearch) {\n    if (root.getAttribute('aria-expanded') === 'true') return;\n    root.setAttribute('aria-expanded', 'true'); active = -1; search.value = ''; renderList();\n    if (focusSearch) setTimeout(() => search.focus(), 0);\n  }\n  function close(refocus) { root.setAttribute('aria-expanded', 'false'); if (refocus) trigger.focus(); }\n  trigger.addEventListener('click', e => {\n    const rm = e.target.closest('[data-rm]');\n    if (rm) { e.stopPropagation(); toggle(rm.dataset.rm); return; }\n    root.getAttribute('aria-expanded') === 'true' ? close() : open(true);\n  });\n  trigger.addEventListener('keydown', e => { if (['Enter', ' ', 'ArrowDown'].includes(e.key)) { e.preventDefault(); open(true); } });\n  search.addEventListener('input', () => { active = 0; renderList(); });\n  search.addEventListener('keydown', e => {\n    const n = visible().length;\n    if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(n - 1, active + 1); renderList(); }\n    else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(0, active - 1); renderList(); }\n    else if (e.key === 'Enter') { e.preventDefault(); const x = visible()[active]; if (x) toggle(x.value); }\n    else if (e.key === 'Escape' || e.key === 'Tab') { close(e.key === 'Escape'); }\n  });\n  listEl.addEventListener('mousedown', e => e.preventDefault());\n  listEl.addEventListener('click', e => { const li = e.target.closest('[data-v]'); if (li) toggle(li.dataset.v); });\n  document.addEventListener('click', e => { if (e.target.isConnected && !root.contains(e.target)) close(); });\n  renderTrigger();\n  return {\n    get: () => selected.slice(),\n    set: vals => { selected = (vals || []).filter(v => o.options.some(x => x.value === v)); renderTrigger(); },\n    setOptions: (options, keep) => { o.options = options; selected = keep ? selected.filter(v => options.some(x => x.value === v)) : []; renderTrigger(); },\n    focus: () => trigger.focus()\n  };\n}\n</script>\n<script>\nconst D = /*__DATA__*/null;\nconst I18N = {\n  fr: { title: 'Rencontrez les bonnes personnes à Toulouse', intro: 'Décrivez votre projet professionnel : nous vous mettons en relation avec des membres de notre réseau qui connaissent votre métier.',\n    s1: 'Vos coordonnées', s1h: 'Pour que nous puissions vous écrire.', prenom: 'Prénom', nom: 'Nom', email: 'Email', tel: 'Téléphone', ville: 'Ville où vous habitez',\n    s2: 'Votre projet', s2h: 'Ces informations nous aident à trouver les bons contacts.', langues: 'Langues parlées', languesH: 'Nous vous écrirons dans ces langues. Plusieurs choix possibles.',\n    metiers: 'Métiers recherchés', metiersH: \"Jusqu'à 5 choix. Tapez pour filtrer la liste.\", parcours: 'Votre parcours en quelques lignes', parcoursH: 'Formation, expérience, ce que vous recherchez.',\n    rgpd: \"J'accepte que Toulouse Way utilise ces informations pour me mettre en relation avec des membres de son réseau. Je peux demander leur suppression à tout moment.\",\n    send: 'Envoyer ma demande', sending: 'Envoi…', note: 'Réponse sous quelques jours.', required: 'Ce champ est obligatoire.', emailErr: 'Indiquez une adresse email valide, par exemple nom@exemple.fr.',\n    chooseOne: 'Choisissez au moins une option.', rgpdErr: 'Cochez cette case pour envoyer votre demande.', choose: 'Choisir…', search: 'Rechercher…', empty: 'Aucun résultat', remove: 'Retirer',\n    doneT: 'Demande envoyée', doneP: 'Merci {p} ! Un email de confirmation vient de vous être envoyé. Nous revenons vers vous dès qu’une mise en relation est possible.', doneA: \"Voir l'agenda des formations\",\n    fail: \"L'envoi n'a pas abouti. Vérifiez votre connexion puis réessayez.\", fixErrors: 'Quelques champs sont à compléter.' },\n  en: { title: 'Meet the right people in Toulouse', intro: 'Tell us about your career plans: we will introduce you to members of our network who know your field.',\n    s1: 'Your details', s1h: 'So that we can write to you.', prenom: 'First name', nom: 'Last name', email: 'Email', tel: 'Phone', ville: 'City you live in',\n    s2: 'Your project', s2h: 'This helps us find the right contacts.', langues: 'Languages you speak', languesH: 'We will write to you in these languages. Choose as many as you like.',\n    metiers: 'Jobs you are looking for', metiersH: 'Up to 5 choices. Type to filter the list.', parcours: 'Your background in a few lines', parcoursH: 'Education, experience, what you are looking for.',\n    rgpd: 'I agree that Toulouse Way may use this information to introduce me to members of its network. I can ask for it to be deleted at any time.',\n    send: 'Send my request', sending: 'Sending…', note: 'We reply within a few days.', required: 'This field is required.', emailErr: 'Enter a valid email address, for example name@example.com.',\n    chooseOne: 'Choose at least one option.', rgpdErr: 'Tick this box to send your request.', choose: 'Choose…', search: 'Search…', empty: 'No results', remove: 'Remove',\n    doneT: 'Request sent', doneP: 'Thank you {p}! A confirmation email is on its way. We will get back to you as soon as an introduction is possible.', doneA: 'See the training calendar',\n    fail: 'Sending failed. Check your connection and try again.', fixErrors: 'A few fields need your attention.' }\n};\nconst lang = D.lang === 'en' ? 'en' : 'fr', t = I18N[lang];\ndocument.documentElement.lang = lang;\ndocument.title = (lang === 'en' ? 'Networking request' : 'Demande de mise en relation') + ' – ' + D.P.nom_asso;\ndocument.documentElement.style.setProperty('--orange', D.P.couleur_principale);\ndocument.documentElement.style.setProperty('--ink', D.P.couleur_encre);\ndocument.querySelectorAll('[data-t]').forEach(el => el.textContent = t[el.dataset.t]);\ndocument.querySelectorAll('.lang a').forEach(a => a.setAttribute('aria-current', a.dataset.l === lang));\nlogo.src = D.P.logo_url; logo.alt = D.P.nom_asso; document.getElementById('logo-link').href = D.P.site_url;\nfoot.textContent = D.P.slogan + ' · ' + D.P.nom_asso;\n\nconst msL = MultiSelect(document.getElementById('ms-langues'), { labelledby: 'l-langues', placeholder: t.choose, search: t.search, empty: t.empty, remove: t.remove,\n  options: D.langues.map(l => ({ value: l.code, label: lang === 'en' ? l.en : l.fr, natif: l.natif })), onChange: () => valid('f-langues', msL.get().length) });\nconst msM = MultiSelect(document.getElementById('ms-metiers'), { labelledby: 'l-metiers', placeholder: t.choose, search: t.search, empty: t.empty, remove: t.remove, max: 5,\n  options: D.metiers.map(m => ({ value: m.code, label: lang === 'en' ? (m.en || m.fr) : m.fr, group: (String(m.groupe || '').split('|')[lang === 'en' ? 1 : 0] || '').trim() })), onChange: () => valid('f-metiers', msM.get().length) });\n\nfunction valid(id, ok) { document.getElementById(id).classList.toggle('invalid', !ok); return !!ok; }\nfunction toast(msg, err) { const el = document.getElementById('toast'); el.textContent = msg; el.className = 'toast show' + (err ? ' err' : ''); setTimeout(() => el.className = 'toast', 4200); }\nconst emailOk = v => /^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(v);\nconst f = document.getElementById('f');\n['prenom', 'nom', 'email'].forEach(n => f[n].addEventListener('blur', () => f[n].closest('.field').classList.toggle('invalid', n === 'email' ? !emailOk(f[n].value.trim()) : !f[n].value.trim())));\nf.addEventListener('submit', async e => {\n  e.preventDefault();\n  const v = n => f[n].value.trim();\n  let ok = true; const firstBad = [];\n  for (const n of ['prenom', 'nom']) { const bad = !v(n); f[n].closest('.field').classList.toggle('invalid', bad); if (bad) { ok = false; firstBad.push(f[n]); } }\n  const be = !emailOk(v('email')); f.email.closest('.field').classList.toggle('invalid', be); if (be) { ok = false; firstBad.push(f.email); }\n  if (!valid('f-langues', msL.get().length)) { ok = false; firstBad.push(msL); }\n  if (!valid('f-metiers', msM.get().length)) { ok = false; firstBad.push(msM); }\n  if (!valid('f-rgpd', f.rgpd.checked)) { ok = false; firstBad.push(f.rgpd); }\n  if (!ok) { alertBox(t.fixErrors); firstBad[0].focus(); return; }\n  alertBox('');\n  send.disabled = true; send.textContent = t.sending;\n  try {\n    const r = await fetch(D.submit, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({\n      prenom: v('prenom'), nom: v('nom'), email: v('email'), telephone: v('telephone'), ville: v('ville'), parcours: v('parcours'),\n      langues: msL.get(), metiers: msM.get(), langue_formulaire: lang, consentement: true }) });\n    const res = await r.json().catch(() => ({}));\n    if (!r.ok || !res.ok) throw new Error(res.message || 'fail');\n    document.getElementById('sheet').innerHTML = `<div class=\"done\" role=\"status\"><div class=\"mark\" aria-hidden=\"true\">✓</div><h2>${t.doneT}</h2><p>${t.doneP.replace('{p}', v('prenom').replace(/[<>&]/g, ''))}</p>${D.agenda ? `<p><a class=\"btn btn-ghost\" href=\"${D.agenda}?lang=${lang}\">${t.doneA}</a></p>` : ''}</div>`;\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  } catch (err) {\n    alertBox(t.fail); send.disabled = false; send.textContent = t.send;\n  }\n});\nfunction alertBox(msg) { const a = document.getElementById('alert'); a.textContent = msg; a.style.display = msg ? 'block' : 'none'; }\n</script>\n</body>\n</html>\n";
// Construit la page publique du formulaire de demande
const P = TW.params($('Paramètres (demande)').all().map(i => i.json));
const q = $('Webhook demande').first().json.query || {};
const L = $('Listes (demande)').all().map(i => i.json).filter(r => r.code).sort((a, b) => (+a.ordre || 0) - (+b.ordre || 0));
const data = {
  P: { nom_asso: P.nom_asso, slogan: P.slogan, logo_url: P.logo_url, site_url: P.site_url, couleur_principale: P.couleur_principale, couleur_encre: P.couleur_encre },
  lang: q.lang === 'en' ? 'en' : 'fr',
  langues: L.filter(r => TW.norm(r.type) === 'langue').map(r => ({ code: TW.norm(r.code), fr: r.libelle_fr, en: r.libelle_en, natif: r.libelle_natif })),
  metiers: L.filter(r => TW.norm(r.type) === 'metier').map(r => ({ code: String(r.code).trim(), fr: r.libelle_fr, en: r.libelle_en, groupe: r.groupe })),
  submit: 'tw-demande-envoi', agenda: 'tw-agenda'
};
return [{ json: { html: TPL.split('/*__DATA__*/null').join(JSON.stringify(data).replace(/</g, '\\u003c')) } }];

// ===== Toulouse Way – bibliothèque commune (emails, pages, utilitaires) =====
const TW = (() => {
  const DEFAULTS = {
    nom_asso: 'Toulouse Way', slogan: 'Mieux vivre ici, ensemble',
    couleur_principale: '#F26716', couleur_encre: '#12343B',
    logo_url: 'https://www.toulouseway.org/assets/logo.png', site_url: 'https://www.toulouseway.org',
    email_gestionnaire: 'contact@toulouseway.org', n8n_url: '', signature: "L'équipe Toulouse Way",
    pied_de_page: 'Toulouse Way · Association loi 1901 · Toulouse',
    score_minimum: '50', max_propositions: '3'
  };
  const RTL = ['ar', 'fa', 'he', 'ur'];
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const list = s => String(s ?? '').split(/[,;]/).map(x => x.trim()).filter(Boolean);
  const norm = s => String(s ?? '').trim().toLowerCase();
  const rnd = n => { const a = 'abcdefghijkmnpqrstuvwxyz23456789'; let s = ''; for (let i = 0; i < n; i++) s += a[Math.floor(Math.random() * a.length)]; return s; };
  const uid = p => `${p}-${Date.now().toString(36).toUpperCase()}${rnd(3).toUpperCase()}`;
  const token = () => rnd(32);

  function params(rows) {
    const P = { ...DEFAULTS };
    for (const r of rows || []) if (r && r.id && String(r.valeur ?? '').trim() !== '') P[String(r.id).trim()] = String(r.valeur).trim();
    P.n8n_url = String(P.n8n_url).replace(/\/+$/, '');
    return P;
  }
  const link = (P, path, q) => `${P.n8n_url}/webhook/${path}` + (q ? '?' + Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&') : '');

  // ---------- Dates (texte « AAAA-MM-JJ », JJ/MM/AAAA ou numéro de série Sheets) ----------
  function isoDate(v) {
    if (v === null || v === undefined || v === '') return '';
    if (typeof v === 'number') { const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return d.toISOString().slice(0, 10); }
    const s = String(v).trim(); let m;
    if ((m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/))) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;
    if ((m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/))) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
    return '';
  }
  const todayParis = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const nowParis = () => todayParis() + ' ' + new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' }).format(new Date());
  const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 864e5);
  function longDate(iso, lang) {
    if (!iso) return '';
    const d = new Date(iso + 'T12:00:00Z');
    try { return new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : (lang || 'fr') , { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(d); }
    catch (e) { return iso; }
  }

  // ---------- Couleurs ----------
  function mix(hex, other, t) {
    const h = x => x.replace('#', '').padEnd(6, '0'); const a = h(hex), b = h(other);
    return '#' + [0, 2, 4].map(i => Math.round(parseInt(a.substr(i, 2), 16) * (1 - t) + parseInt(b.substr(i, 2), 16) * t).toString(16).padStart(2, '0')).join('');
  }

  // ---------- Rendu d'un texte de template ----------
  // {{variable}} = valeur (échappée) · **gras** · [[Texte du bouton|variable_lien]] = bouton
  // Un bloc qui ne contient que {{details_...}} ou {{liste_...}} insère un encadré HTML.
  function button(P, label, url, quiet) {
    const c = P.couleur_principale;
    const style = quiet
      ? `display:inline-block;padding:11px 20px;margin:4px 8px 4px 0;border:2px solid ${c};color:${mix(c, '#000000', 0.25)};background:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`
      : `display:inline-block;padding:13px 22px;margin:4px 8px 4px 0;background:${c};color:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`;
    return `<a href="${esc(url)}" style="${style}">${esc(label)}</a>`;
  }
  function renderText(text, vars, P) {
    const html = {}; for (const k in vars) if (/^(details_|liste_)/.test(k)) html[k] = true;
    const blocks = String(text ?? '').replace(/\r/g, '').split(/\n\s*\n/).map(b => b.trim()).filter(Boolean);
    let nb = 0;
    return blocks.map(b => {
      const only = b.match(/^\{\{(\w+)\}\}$/);
      if (only && html[only[1]]) return vars[only[1]] || '';
      const buttonsOnly = /^(\s*\[\[[^\]]+\]\]\s*)+$/.test(b);
      let out = '', last = 0;
      const re = /\{\{(\w+)\}\}|\[\[([^\]|]+)\|(\w+)\]\]|\*\*(.+?)\*\*/g; let m;
      while ((m = re.exec(b))) {
        out += esc(b.slice(last, m.index)).replace(/\n/g, '<br>');
        if (m[1]) out += html[m[1]] ? (vars[m[1]] || '') : esc(vars[m[1]] ?? '');
        else if (m[2]) out += button(P, m[2].trim(), vars[m[3]] || '#', nb++ > 0);
        else out += '<strong>' + esc(m[4]).replace(/\{\{(\w+)\}\}/g, (_, k) => html[k] ? '' : esc(vars[k] ?? '')) + '</strong>';
        last = re.lastIndex;
      }
      out += esc(b.slice(last)).replace(/\n/g, '<br>');
      return buttonsOnly ? `<p style="margin:22px 0">${out}</p>` : `<p style="margin:0 0 16px">${out}</p>`;
    }).join('\n');
  }
  const fill = (text, vars) => String(text ?? '').replace(/\{\{(\w+)\}\}/g, (_, k) => /^(details_|liste_)/.test(k) ? '' : String(vars[k] ?? ''));

  // ---------- Choix des templates selon les langues ----------
  function pick(templates, cle, langs) {
    const rows = (templates || []).filter(t => norm(t.cle) === norm(cle) && String(t.contenu || '').trim());
    const by = {}; for (const t of rows) by[norm(t.langue)] = t;
    const found = []; for (const l of (langs || []).map(norm)) if (by[l] && !found.includes(by[l])) found.push(by[l]);
    if (!found.length) for (const l of ['fr', 'en']) if (by[l]) { found.push(by[l]); break; }
    if (!found.length && rows[0]) found.push(rows[0]);
    return found;
  }

  // ---------- Mise en page des emails ----------
  function layout(P, sections, preheader) {
    const c = P.couleur_principale, ink = P.couleur_encre;
    const body = sections.map((s, i) => {
      const rtl = RTL.includes(norm(s.lang));
      return `${i ? `<tr><td style="padding:0 36px"><div style="border-top:1px dashed ${mix(c, '#ffffff', 0.55)};margin:8px 0 0"></div></td></tr>` : ''}
<tr><td dir="${rtl ? 'rtl' : 'ltr'}" lang="${esc(s.lang)}" style="padding:28px 36px 12px;text-align:${rtl ? 'right' : 'left'};font-family:'Atkinson Hyperlegible',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:${ink}">${s.html}</td></tr>`;
    }).join('');
    return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(P.nom_asso)}</title></head>
<body style="margin:0;padding:0;background:#EEF2F2">
<div style="display:none;max-height:0;overflow:hidden;opacity:0">${esc(preheader || '')}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#EEF2F2;padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden">
<tr><td style="padding:22px 36px 18px;border-bottom:4px solid ${c}">
  <a href="${esc(P.site_url)}" style="text-decoration:none"><img src="${esc(P.logo_url)}" alt="${esc(P.nom_asso)}" height="44" style="height:44px;max-width:220px;display:block;border:0"></a>
</td></tr>
${body}
<tr><td style="padding:12px 36px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:${ink}">${esc(P.signature)}</td></tr>
<tr><td style="background:${ink};padding:20px 36px;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:1.5;color:#D8E3E4">
  <div style="color:#ffffff;font-weight:700;font-size:15px">${esc(P.slogan)}</div>
  <div style="margin-top:6px">${esc(P.pied_de_page)}</div>
  <div style="margin-top:6px"><a href="${esc(P.site_url)}" style="color:${mix(c, '#ffffff', 0.35)}">${esc(String(P.site_url).replace(/^https?:\/\//, ''))}</a></div>
</td></tr></table></td></tr></table></body></html>`;
  }

  // Construit un email {sujet, html} à partir d'une clé de template et d'une liste de langues
  function email(templates, cle, langs, vars, P) {
    const rows = pick(templates, cle, langs);
    if (!rows.length) throw new Error(`Template introuvable : ${cle}`);
    const sujets = [...new Set(rows.map(t => fill(t.sujet, vars).trim()).filter(Boolean))];
    const sections = rows.map(t => ({ lang: norm(t.langue), html: renderText(t.contenu, vars, P) }));
    return { sujet: sujets.slice(0, 2).join(' / '), html: layout(P, sections, fill(rows[0].sujet, vars)), langues: rows.map(t => norm(t.langue)) };
  }

  // ---------- Encadrés ----------
  function box(P, inner) {
    return `<div style="background:${mix(P.couleur_principale, '#ffffff', 0.9)};border-left:4px solid ${P.couleur_principale};border-radius:10px;padding:16px 18px;margin:6px 0 20px">${inner}</div>`;
  }
  const L = {
    fr: { date: 'Date', heure: 'Horaire', lieu: 'Lieu', lien: 'En ligne', intervenant: 'Animé par', type: 'Type', metiers: 'Métiers recherchés', langues: 'Langues', ville: 'Ville', parcours: 'Parcours', email: 'Email', tel: 'Téléphone' },
    en: { date: 'Date', heure: 'Time', lieu: 'Venue', lien: 'Online', intervenant: 'Led by', type: 'Type', metiers: 'Target jobs', langues: 'Languages', ville: 'City', parcours: 'Background', email: 'Email', tel: 'Phone' }
  };
  const lab = lang => L[norm(lang)] || L.fr;
  function rowsTable(rows) {
    return '<table role="presentation" cellpadding="0" cellspacing="0" style="font-size:15px;line-height:1.5">' +
      rows.filter(r => r[1]).map(([k, v]) => `<tr><td style="padding:3px 16px 3px 0;color:#4A6266;vertical-align:top;white-space:nowrap">${esc(k)}</td><td style="padding:3px 0;vertical-align:top">${v}</td></tr>`).join('') + '</table>';
  }
  function sessionTitle(s, lang) { return (norm(lang) === 'en' && s.titre_en) ? s.titre_en : (s.titre || ''); }
  function detailsSession(P, s, lang) {
    const l = lab(lang), iso = isoDate(s.date);
    const h = s.heure_debut ? (s.heure_fin ? `${s.heure_debut} – ${s.heure_fin}` : s.heure_debut) : '';
    return box(P, `<div style="font-size:18px;font-weight:700;margin-bottom:8px">${esc(sessionTitle(s, lang))}</div>` + rowsTable([
      [l.date, esc(longDate(iso, lang))], [l.heure, esc(h)], [l.lieu, esc(s.lieu)],
      [l.lien, s.lien_visio ? `<a href="${esc(s.lien_visio)}" style="color:${P.couleur_principale}">${esc(s.lien_visio)}</a>` : ''],
      [l.intervenant, esc(s.intervenant)]
    ]) + (s.infos_pratiques ? `<div style="margin-top:10px">${esc(s.infos_pratiques)}</div>` : ''));
  }
  // Coordonnées d'un contact : sans libellés, donc lisible dans toutes les langues
  function detailsContact(P, c) {
    const lines = [
      `<div style="font-size:18px;font-weight:700">${esc(`${c.prenom || ''} ${c.nom || ''}`.trim())}</div>`,
      [c.poste, c.entreprise].filter(Boolean).length ? `<div>${esc([c.poste, c.entreprise].filter(Boolean).join(' · '))}</div>` : '',
      c.email ? `<div>✉️ <a dir="ltr" href="mailto:${esc(c.email)}" style="color:${P.couleur_principale};unicode-bidi:isolate">${esc(c.email)}</a></div>` : '',
      c.telephone ? `<div>📞 <a dir="ltr" href="tel:${esc(String(c.telephone).replace(/\s/g, ''))}" style="color:${P.couleur_principale};unicode-bidi:isolate">${esc(c.telephone)}</a></div>` : '',
      c.ville ? `<div>📍 ${esc(c.ville)}</div>` : ''
    ];
    return box(P, lines.join(''));
  }
  function libelles(listes, type, codes, lang) {
    const m = {}; for (const r of listes || []) if (norm(r.type) === type) m[norm(r.code)] = (norm(lang) === 'en' && r.libelle_en) ? r.libelle_en : (r.libelle_fr || r.code);
    return list(codes).map(c => m[norm(c)] || c).join(', ');
  }
  function detailsDemandeur(P, d, lang, listes, withContact) {
    const l = lab(lang);
    return box(P, `<div style="font-size:18px;font-weight:700;margin-bottom:8px">${esc(`${d.prenom || ''} ${d.nom || ''}`.trim())}</div>` + rowsTable([
      [l.metiers, esc(libelles(listes, 'metier', d.metiers, lang))], [l.langues, esc(libelles(listes, 'langue', d.langues, lang))],
      [l.ville, esc(d.ville)], [l.parcours, esc(d.parcours)],
      [l.email, withContact && d.email ? `<a href="mailto:${esc(d.email)}" style="color:${P.couleur_principale}">${esc(d.email)}</a>` : ''],
      [l.tel, withContact ? esc(d.telephone) : '']
    ]));
  }

  // ---------- Page de réponse (après un clic dans un email) ----------
  function page(P, o) {
    const c = P.couleur_principale, ink = P.couleur_encre;
    const tone = { ok: '#2E7D5B', warn: '#B7791F', err: '#B23A2E' }[o.tone || 'ok'];
