  <div class=\"side\">${s.places > 0 ? (full ? `<span class=\"full\">${t.full}</span>` : `<div class=\"seats\">${t.left(s.restantes)}<div class=\"meter\" aria-hidden=\"true\"><i style=\"width:${Math.min(100, Math.round(100 * (s.places - s.restantes) / s.places))}%\"></i></div></div>`) : '<span></span>'}\n        <button class=\"btn btn-primary\" type=\"button\" data-reg=\"${esc(s.id)}\" ${full ? 'disabled' : ''}>${t.register}</button></div></article>`;\n  }\n  list.innerHTML = html;\n}\nlist.addEventListener('click', e => { const b = e.target.closest('[data-reg]'); if (b) openForm(sessions.find(s => s.id === b.dataset.reg)); });\n\nconst dlg = document.getElementById('dlg');\ndocument.getElementById('dlg-x').onclick = () => dlg.close();\ndlg.addEventListener('click', e => { if (e.target === dlg) dlg.close(); });\nfunction openForm(s) {\n  document.getElementById('dlg-title').textContent = title(s);\n  document.getElementById('dlg-meta').textContent = [fmt(s.date, { weekday: 'long', day: 'numeric', month: 'long' }), hours(s), where(s)].filter(Boolean).join(' · ');\n  document.getElementById('dlg-body').innerHTML = `<form id=\"rf\" novalidate><div class=\"alert\" id=\"ralert\" role=\"alert\"></div>\n    <div class=\"grid-2\"><div class=\"field\"><label for=\"r-prenom\">${t.prenom} <span class=\"req\">*</span></label><input class=\"input\" id=\"r-prenom\" name=\"prenom\" autocomplete=\"given-name\" maxlength=\"80\"><span class=\"err-msg\">${t.required}</span></div>\n    <div class=\"field\"><label for=\"r-nom\">${t.nom} <span class=\"req\">*</span></label><input class=\"input\" id=\"r-nom\" name=\"nom\" autocomplete=\"family-name\" maxlength=\"80\"><span class=\"err-msg\">${t.required}</span></div></div>\n    <div class=\"field\"><label for=\"r-email\">${t.email} <span class=\"req\">*</span></label><input class=\"input\" id=\"r-email\" name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"120\"><span class=\"err-msg\">${t.emailErr}</span></div>\n    <div class=\"field\"><label for=\"r-tel\">${t.tel}</label><input class=\"input\" id=\"r-tel\" name=\"telephone\" type=\"tel\" autocomplete=\"tel\" maxlength=\"30\"></div>\n    <div class=\"field\"><label class=\"check\"><input type=\"checkbox\" name=\"rgpd\"><span>${t.rgpd}</span></label><span class=\"err-msg\">${t.rgpdErr}</span></div>\n    <button class=\"btn btn-primary\" type=\"submit\" id=\"rsend\">${t.send}</button></form>`;\n  const rf = document.getElementById('rf');\n  rf.addEventListener('submit', e => submit(e, s, rf));\n  dlg.showModal(); setTimeout(() => rf.prenom.focus(), 30);\n}\nasync function submit(e, s, rf) {\n  e.preventDefault();\n  const v = n => rf[n].value.trim(), bad = [];\n  const mark = (el, isBad) => { el.closest('.field').classList.toggle('invalid', isBad); if (isBad) bad.push(el); };\n  mark(rf.prenom, !v('prenom')); mark(rf.nom, !v('nom')); mark(rf.email, !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(v('email'))); mark(rf.rgpd, !rf.rgpd.checked);\n  if (bad.length) { bad[0].focus(); return; }\n  const btn = document.getElementById('rsend'), al = document.getElementById('ralert');\n  btn.disabled = true; btn.textContent = t.sending; al.style.display = 'none';\n  try {\n    const r = await fetch(D.submit, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session_id: s.id, prenom: v('prenom'), nom: v('nom'), email: v('email'), telephone: v('telephone'), langue: lang, consentement: true }) });\n    const res = await r.json().catch(() => ({}));\n    if (!res.ok) { al.textContent = t.errors[res.code] || t.fail; al.style.display = 'block'; btn.disabled = false; btn.textContent = t.send; if (res.code === 'complet') { s.restantes = 0; render(); } return; }\n    s.restantes = Math.max(0, (s.restantes || 0) - 1); render();\n    document.getElementById('dlg-body').innerHTML = `<div class=\"done\" role=\"status\"><div class=\"mark\" aria-hidden=\"true\">✓</div><h3>${t.doneT}</h3><p>${t.doneP}</p><button class=\"btn btn-g