ition:relative}\n.step b{font-family:var(--f-display);font-size:28px;font-weight:800;display:block;line-height:1.1}.step span{font-size:14px;color:var(--ink-2)}\n.step.hot{background:var(--orange-soft)}.step.good{background:var(--ok-soft)}\n.side-stats{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px;font-size:14px;color:var(--muted)}.side-stats b{color:var(--ink)}\n/* Tables */\n.toolbar{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}\n.toolbar .input,.toolbar .select{width:auto;min-width:200px;flex:1 1 200px;max-width:340px}\n\n.tscroll{width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-radius:var(--r-md)}\ntable.t{width:100%;border-collapse:collapse;background:#fff;border-radius:var(--r-md);overflow:hidden}\n.t th{text-align:start;font-size:13px;color:var(--muted);font-weight:700;padding:12px 14px;border-bottom:1px solid var(--line);background:#fff}\n.t td{padding:12px 14px;border-bottom:1px solid var(--mist);vertical-align:top;font-size:15px}\n.t tr.click{cursor:pointer}.t tr.click:hover td{background:#FAFBFB}\n.t td .muted{color:var(--muted);font-size:14px}\n.t .num{text-align:end;font-variant-numeric:tabular-nums}\n.mini-meter{display:flex;align-items:center;gap:8px}.mini-meter i{display:block;width:80px;height:6px;border-radius:3px;background:var(--mist);overflow:hidden}.mini-meter i b{display:block;height:100%;background:var(--orange)}\n@media (max-width:900px) and (min-width:761px){.t td,.t th{padding:10px 10px}.t td{font-size:14px}}\n@media (max-width:760px){.t thead{display:none}.t,.t tbody,.t tr,.t td{display:block;width:100%}.t tr{border-bottom:8px solid var(--mist)}.t td{border:0;padding:6px 14px}.t td[data-l]::before{content:attr(data-l);display:block;font-size:12px;color:var(--muted);font-weight:700}.t .num{text-align:start}}\n.empty{background:#fff;border-radius:var(--r-md);padding:36px;text-align:center;color:var(--muted)}\n.todo{list-style:none;margin:0;padding:0}\n.todo li{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--mist);flex-wrap:wrap}\n.todo li:last-child{border-bottom:0}.todo .who{min-width:0}.todo .who b{display:block}.todo .who span{color:var(--muted);font-size:14px}\n.todo .acts{display:flex;gap:8px}\n/* Tiroir */\n.drawer-bg{position:fixed;inset:0;background:rgba(18,52,59,.45);z-index:60;display:none}\n.drawer{position:fixed;top:0;inset-inline-end:0;height:100vh;width:min(620px,100vw);background:#fff;z-index:61;display:flex;flex-direction:column;transform:translateX(105%);transition:transform .22s ease}\n.drawer.open{transform:none}.drawer-bg.open{display:block}\n.drawer header{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;align-items:flex-start;justify-content:space-between;gap:12px}\n.drawer header h2{font-size:24px}.drawer header p{margin:4px 0 0;color:var(--muted);font-size:14px}\n.drawer .body{flex:1;overflow:auto;padding:22px 24px}\n.drawer footer{padding:14px 24px;border-top:1px solid var(--line);display:flex;gap:10px;justify-content:space-between;flex-wrap:wrap}\n.drawer footer .r{display:flex;gap:10px;margin-inline-start:auto}\n.x{border:0;background:var(--mist);width:38px;height:38px;border-radius:50%;cursor:pointer;font-size:20px;flex:none}\n.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin:-6px 0 18px;overflow-x:auto}\n.tabs button{border:0;background:none;padding:10px 12px;font-weight:700;color:var(--muted);border-bottom:3px solid transparent;cursor:pointer;white-space:nowrap}\n.tabs button[aria-selected=true]{color:var(--ink);border-bottom-color:var(--orange)}\n.switch{display:flex;align-items:flex-start;gap:12px;cursor:pointer}\n.switch input{appearance:none;width:44px;height:26px;border-radius:999px;background:var(--line);position:relative;flex:none;cursor:pointer;transition:background .15s;margin:0}\n.switch input::after{content:\"\";position:absolute;top:3px;inset-inline-start:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .15s;box-shadow:0 1px 2px rgba(0,0,0,.2)}\n.switch input:checked{background:var(--ok)}.switch input:checked::after{transform:translateX(18px)}\n[dir=rtl] .switch input:checked::after{transform:translateX(-18px)}\n.switch b{display:block}.switch span{color:var(--muted);font-size:14px}\n.dl{display:grid;grid-template-columns:140px 1fr;gap:8px 16px;margin:0 0 20px}.dl dt{color:var(--muted);font-size:14px}.dl dd{margin:0}\n.props{list-style:none;padding:0;margin:0}.props li{border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin-bottom:10px}\n.props .top{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center}\n.props .why{font-size:14px;color:var(--muted);margin-top:4px}.props .acts{display:flex;gap:8px;margin-top:10px}\n/* Templates */\n.tpl-layout{display:grid;grid-template-columns:280px minmax(0,1fr);gap:20px;align-items:start}\n.tpl-layout>*,.tpl-edit>*,.cols>*,.grid-2>*{min-width:0}\n@media (max-width:1000px){.tpl-layout{grid-template-columns:minmax(0,1fr)}.tpl-list{display:none}.tpl-pick{display:flex!important}}\n.tpl-pick{display:none}\n.lang-pick{display:none}\n.lang-tabs{margin-bottom:10px}.lang-add{display:flex;justify-content:flex-end;margin:0 0 16px}.lang-add:empty{display:none}\n@media (max-width:1000px){.lang-tabs{display:none}.lang-pick{display:flex}}\n.tpl-list{background:#fff;border-radius:var(--r-md);padding:10px}\n.tpl-list h3{font-size:14px;color:var(--muted);font-family:var(--f-body);font-weight:700;margin:12px 10px 6px}\n.tpl-list button{display:block;width:100%;text-align:start;border:0;background:none;border-radius:8px;padding:9px 10px;cursor:pointer}\n.tpl-list button:hover{background:var(--mist)}.tpl-list button[aria-current=true]{background:var(--orange-soft)}\n.tpl-list button b{display:block;font-size:15px}.tpl-list button span{font-size:13px;color:var(--muted)}\n.tpl-edit{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}\n@media (max-width:1600px){.tpl-edit{grid-template-columns:minmax(0,1fr)}}\n.vars{display:flex;flex-wrap:wrap;gap:6px;margin:-4px 0 14px}\n.vars button{border:1px dashed var(--line);background:var(--mist);border-radius:6px;padding:3px 8px;font-size:13px;cursor:pointer;font-family:ui-monospace,Menlo,monospace}\n.vars button:hover{border-color:var(--ink)}\n.textarea.code{min-height:320px;font-size:15px;line-height:1.6}\n.preview{border:1px solid var(--line);border-radius:var(--r-md);overflow:hidden;background:#EEF2F2}\n.preview .pv-head{background:#fff;padding:10px 14px;font-size:14px;border-bottom:1px solid var(--line)}\n.preview iframe{width:100%;height:620px;border:0;display:block;background:#EEF2F2}\n.help{background:var(--mist);border-radius:10px;padding:12px 14px;font-size:14px;color:var(--ink-2);margin-bottom:16px}\n.help code{background:#fff;border-radius:4px;padding:1px 5px;overflow-wrap:anywhere}\n.preview iframe{max-width:100%}\n@media (max-width:600px){.preview iframe{height:520px}.panel{padding:18px 16px}.head h1{font-size:28px}.drawer .body,.drawer header,.drawer footer{padding-left:16px;padding-right:16px}.dl{grid-template-columns:1fr;gap:2px}.dl dd{margin-bottom:8px}.kpi b{font-size:32px}}\n.links .row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--mist)}\n.links .row:last-child{border-bottom:0}.links .row b{min-width:180px}.links code{flex:1;min-width:0;overflow-wrap:anywhere;background:var(--mist);padding:6px 10px;border-radius:6px;font-size:13px}\n.color-in{display:flex;gap:8px;align-items:center}.color-in input[type=color]{width:46px;height:46px;border:1.5px solid var(--line);border-radius:8px;padding:2px;background:#fff}\n.loading{position:fixed;top:0;inset-inline:0;height:3px;background:var(--orange);transform-origin:left;animation:ld 1.2s ease-in-out infinite;z-index:95;display:none}\n@keyframes ld{0%{transform:scaleX(0)}50%{transform:scaleX(.7)}100%{transform:scaleX(1);opacity:0}}\n</style>\n</head>\n<body>\n<div class=\"loading\" id=\"loading\"></div>\n<section id=\"login\">\n  <div class=\"login-side\">\n    <span class=\"logo\"><img id=\"lg-logo\" alt=\"\"></span>\n    <div><h1 id=\"lg-slogan\"></h1><p>Demandes de mise en relation, contacts, formations et événements : tout se pilote d'ici.</p></div>\n    <svg viewBox=\"0 0 1200 90\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><path d=\"M-10 62 C 200 14, 360 84, 580 44 S 920 6, 1080 40 S 1180 70, 1215 40\" fill=\"none\" stroke=\"var(--orange)\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-dasharray=\"1 14\"/></svg>\n    <span></span>\n  </div>\n  <div class=\"login-form\">\n    <form id=\"lf\" novalidate>\n      <h2>Espace gestion</h2><p>Connectez-vous avec l'identifiant de l'association.</p>\n      <div class=\"alert-box\" id=\"lerr\" role=\"alert\" style=\"display:none;background:var(--err-soft);color:var(--err);padding:12px 14px;border-radius:8px;margin-bottom:16px\"></div>\n      <div class=\"field\"><label for=\"lu\">Identifiant</label><input class=\"input\" id=\"lu\" autocomplete=\"username\" required></div>\n      <div class=\"field\"><label for=\"lp\">Mot de passe</label><input class=\"input\" id=\"lp\" type=\"password\" autocomplete=\"current-password\" required></div>\n      <button class=\"btn btn-primary\" style=\"width:100%\" id=\"lbtn\">Se connecter</button>\n    </form>\n  </div>\n</section>\n\n<div id=\"app\">\n  <div class=\"m-top\"><span class=\"logo\"><img id=\"mt-logo\" alt=\"\"></span><button type=\"button\" id=\"logout-m\">Se déconnecter</button></div>\n  <aside>\n    <span class=\"logo\"><img id=\"ap-logo\" alt=\"\"></span>\n    <nav class=\"main\" id=\"nav\" aria-label=\"Sections\"></nav>\n    <div class=\"bottom\"><div id=\"who\">Connecté</div><button type=\"button\" id=\"logout\">Se déconnecter</button></div>\n  </aside>\n  <main class=\"content\" id=\"view\" tabindex=\"-1\"></main>\n</div>\n\n<div class=\"drawer-bg\" id=\"dbg\"></div>\n<div class=\"drawer\" id=\"drawer\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"d-title\">\n  <header><div><h2 id=\"d-title\"></h2><p id=\"d-sub\"></p></div><button class=\"x\" type=\"button\" id=\"d-x\" aria-label=\"Fermer\">×</button></header>\n  <div class=\"body\" id=\"d-body\"></div>\n  <footer id=\"d-foot\"></footer>\n</div>\n<div class=\"tip\" id=\"tip\"></div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>// ===== Toulouse Way – bibliothèque commune (emails, pages, utilitaires) =====\nconst TW = (() => {\n  const DEFAULTS = {\n    nom_asso: 'Toulouse Way', slogan: 'Mieux vivre ici, ensemble',\n    couleur_principale: '#F26716', couleur_encre: '#12343B',\n    logo_url: 'https://www.toulouseway.org/assets/logo.png', site_url: 'https://www.toulouseway.org',\n    email_gestionnaire: 'contact@toulouseway.org', n8n_url: '', signature: \"L'équipe Toulouse Way\",\n    pied_de_page: 'Toulouse Way · Association loi 1901 · Toulouse',\n    score_minimum: '50', max_propositions: '3'\n  };\n  const RTL = ['ar', 'fa', 'he', 'ur'];\n  const esc = s => String(s ?? '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\n  const list = s => String(s ?? '').split(/[,;]/).map(x => x.trim()).filter(Boolean);\n  const norm = s => String(s ?? '').trim().toLowerCase();\n  const rnd = n => { const a = 'abcdefghijkmnpqrstuvwxyz23456789'; let s = ''; for (let i = 0; i < n; i++) s += a[Math.floor(Math.random() * a.length)]; return s; };\n  const uid = p => `${p}-${Date.now().toString(36).toUpperCase()}${rnd(3).toUpperCase()}`;\n  const token = () => rnd(32);\n\n  function params(rows) {\n    const P = { ...DEFAULTS };\n    for (const r of rows || []) if (r && r.id && String(r.valeur ?? '').trim() !== '') P[String(r.id).trim()] = String(r.valeur).trim();\n    P.n8n_url = String(P.n8n_url).replace(/\\/+$/, '');\n    return P;\n  }\n  const link = (P, path, q) => `${P.n8n_url}/webhook/${path}` + (q ? '?' + Object.entries(q).map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join('&') : '');\n\n  // ---------- Dates (texte « AAAA-MM-JJ », JJ/MM/AAAA ou numéro de série Sheets) ----------\n  function isoDate(v) {\n    if (v === null || v === undefined || v === '') return '';\n    if (typeof v === 'number') { const d = new Date(Date.UTC(1899, 11, 30) + Math.floor(v) * 864e5); return d.toISOString().slice(0, 10); }\n    const s = String(v).trim(); let m;\n    if ((m = s.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})/))) return `${m[1]}-${m[2].padStart(2, '0')}-${m[3].padStart(2, '0')}`;\n    if ((m = s.match(/^(\\d{1,2})\\/(\\d{1,2})\\/(\\d{4})/))) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;\n    return '';\n  }\n  const todayParis = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Europe/Paris', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());\n  const nowParis = () => todayParis() + ' ' + new Intl.DateTimeFormat('fr-FR', { timeZone: 'Europe/Paris', hour: '2-digit', minute: '2-digit' }).format(new Date());\n  const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 864e5);\n  function longDate(iso, lang) {\n    if (!iso) return '';\n    const d = new Date(iso + 'T12:00:00Z');\n    try { return new Intl.DateTimeFormat(lang === 'en' ? 'en-GB' : (lang || 'fr') , { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(d); }\n    catch (e) { return iso; }\n  }\n\n  // ---------- Couleurs ----------\n  function mix(hex, other, t) {\n    const h = x => x.replace('#', '').padEnd(6, '0'); const a = h(hex), b = h(other);\n    return '#' + [0, 2, 4].map(i => Math.round(parseInt(a.substr(i, 2), 16) * (1 - t) + parseInt(b.substr(i, 2), 16) * t).toString(16).padStart(2, '0')).join('');\n  }\n\n  // ---------- Rendu d'un texte de template ----------\n  // {{variable}} = valeur (échappée) · **gras** · [[Texte du bouton|variable_lien]] = bouton\n  // Un bloc qui ne contient que {{details_...}} ou {{liste_...}} insère un encadré HTML.\n  function button(P, label, url, quiet) {\n    const c = P.couleur_principale;\n    const style = quiet\n      ? `display:inline-block;padding:11px 20px;margin:4px 8px 4px 0;border:2px solid ${c};color:${mix(c, '#000000', 0.25)};background:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`\n      : `display:inline-block;padding:13px 22px;margin:4px 8px 4px 0;background:${c};color:#ffffff;border-radius:999px;font-weight:700;text-decoration:none;font-size:15px`;\n    return `<a href=\"${esc(url)}\" style=\"${style}\">${esc(label)}</a>`;\n  }\n  function renderText(text, vars, P) {\n    const html = {}; for (const k in vars) if (/^(details_|liste_)/.test(k)) html[k] = true;\n    const blocks = String(text ?? '').replace(/\\r/g, '').split(/\\n\\s*\\n/).map(b => b.trim()).filter(Boolean);\n    let nb = 0;\n    return blocks.map(b => {\n      const only = b.match(/^\\{\\{(\\w+)\\}\\}$/);\n      if (only && html[only[1]]) return vars[only[1]] || '';\n      const buttonsOnly = /^(\\s*\\[\\[[^\\]]+\\]\\]\\s*)+$/.test(b);\n      let out = '', last = 0;\n      const re = /\\{\\{(\\w+)\\}\\}|\\[\\[([^\\]|]+)\\|(\\w+)\\]\\]|\\*\\*(.+?)\\*\\*/g; let m;\n      while ((m = re.exec(b))) {\n        out += esc(b.slice(last, m.index)).replace(/\\n/g, '<br>');\n        if (m[1]) out += html[m[1]] ? (vars[m[1]] || '') : esc(vars[m[1]] ?? '');\n        else if (m[2]) out += button(P, m[2].trim(), vars[m[3]] || '#', nb++ > 0);\n        else out += '<strong>' + esc(m[4]).replace(/\\{\\{(\\w+)\\}\\}/g, (_, k) => html[k] ? '' : esc(vars[k] ?? '')) + '</strong>';\n        last = re.lastIndex;\n      }\n      out += esc(b.slice(last)).replace(/\\n/g, '<br>');\n      return buttonsOnly ? `<p style=\"margin:22px 0\">${out}</p>` : `<p style=\"margin:0 0 16px\">${out}</p>`;\n    }).join('\\n');\n  }\n  const fill = (text, vars) => String(text ?? '').replace(/\\{\\{(\\w+)\\}\\}/g, (_, k) => /^(details_|liste_)/.test(k) ? '' : String(vars[k] ?? ''));\n\n  // ---------- Choix des templates selon les langues ----------\n  function pick(templates, cle, langs) {\n    const rows = (templates || []).filter(t => norm(t.cle) === norm(cle) && String(t.contenu || '').trim());\n    const by = {}; for (const t of rows) by[norm(t.langue)] = t;\n    const found = []; for (const l of (langs || []).map(norm)) if (by[l] && !found.includes(by[l])) found.push(by[l]);\n    if (!found.length) for (const l of ['fr', 'en']) if (by[l]) { found.push(by[l]); break; }\n    if (!found.length && rows[0]) found.push(rows[0]);\n    return found;\n  }\n\n  // ---------- Mise en page des emails ----------\n  function layout(P, sections, preheader) {\n    const c = P.couleur_principale, ink = P.couleur_encre;\n    const body = sections.map((s, i) => {\n      const rtl = RTL.includes(norm(s.lang));\n      return `${i ? `<tr><td style=\"padding:0 36px\"><div style=\"border-top:1px dashed ${mix(c, '#ffffff', 0.55)};margin:8px 0 0\"></div></td></tr>` : ''}\n<tr><td dir=\"${rtl ? 'rtl' : 'ltr'}\" lang=\"${esc(s.lang)}\" style=\"padding:28px 36px 12px;text-align:${rtl ? 'right' : 'left'};font-family:'Atkinson Hyperlegible',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:${ink}\">${s.html}</td></tr>`;\n    }).join('');\n    return `<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>${esc(P.nom_asso)}</title></head>\n<body style=\"margin:0;padding:0;background:#EEF2F2\">\n<div style=\"display:none;max-height:0;overflow:hidden;opacity:0\">${esc(preheader || '')}</div>\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#EEF2F2;padding:24px 12px\"><tr><td align=\"center\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:600px;background:#ffffff;border-radius:14px;overflow:hidden\">\n<tr><td style=\"padding:22px 36px 18px;border-bottom:4px solid ${c}\">\n  <a href=\"${esc(P.site_url)}\" style=\"text-decoration:none\"><img src=\"${esc(P.logo_url)}\" alt=\"${esc(P.nom_asso)}\" height=\"44\" style=\"height:44px;max-width:220px;display:block;border:0\"></a>\n</td></tr>\n${body}\n<tr><td style=\"padding:12px 36px 28px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:${ink}\">${esc(P.signature)}</td></tr>\n<tr><td style=\"background:${ink};padding:20px 36px;font-family:Arial,Helvetica,sans-serif;font-size:13px;line-height:1.5;color:#D8E3E4\">\n  <div style=\"color:#ffffff;font-weight:700;font-size:15px\">${esc(P.slogan)}</div>\n  <div style=\"margin-top:6px\">${esc(P.pied_de_page)}</div>\n  <div style=\"margin-top:6px\"><a href=\"${esc(P.site_url)}\" style=\"color:${mix(c, '#ffffff', 0.35)}\">${esc(String(P.site_url).replace(/^https?:\\/\\//, ''))}</a></div>\n</td></tr></table></td></tr></table></body></html>`;\n  }\n\n  // Construit un email {sujet, html} à partir d'une clé de template et d'une liste de langues\n  function email(templates, cle, langs, vars, P) {\n    const rows = pick(templates, cle, langs);\n    if (!rows.length) throw new Error(`Template introuvable : ${cle}`);\n    const sujets = [...new Set(rows.map(t => fill(t.sujet, vars).trim()).filter(Boolean))];\n    const sections = rows.map(t => ({ lang: norm(t.langue), html: renderText(t.contenu, vars, P) }));\n    return { sujet: sujets.slice(0, 2).join(' / '), html: layout(P, sections, fill(rows[0].sujet, vars)), langues: rows.map(t => norm(t.langue)) };\n  }\n\n  // ---------- Encadrés ----------\n  function box(P, inner) {\n    return `<div style=\"background:${mix(P.couleur_principale, '#ffffff', 0.9)};border-left:4px solid ${P.couleur_principale};border-radius:10px;padding:16px 18px;margin:6px 0 20px\">${inner}</div>`;\n  }\n  const L = {\n    fr: { date: 'Date', heure: 'Horaire', lieu: 'Lieu', lien: 'En ligne', intervenant: 'Animé par', type: 'Type', metiers: 'Métiers recherchés', langues: 'Langues', ville: 'Ville', parcours: 'Parcours', email: 'Email', tel: 'Téléphone' },\n    en: { date: 'Date', heure: 'Time', lieu: 'Venue', lien: 'Online', intervenant: 'Led by', type: 'Type', metiers: 'Target jobs', langues: 'Languages', ville: 'City', parcours: 'Background', email: 'Email', tel: 'Phone' }\n  };\n  const lab = lang => L[norm(lang)] || L.fr;\n  function rowsTable(rows) {\n    return '<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"font-size:15px;line-height:1.5\">' +\n      rows.filter(r => r[1]).map(([k, v]) => `<tr><td style=\"padding:3px 16px 3px 0;color:#4A6266;vertical-align:top;white-space:nowrap\">${esc(k)}</td><td style=\"padding:3px 0;vertical-align:top\">${v}</td></tr>`).join('') + '</table>';\n  }\n  function sessionTitle(s, lang) { return (norm(lang) === 'en' && s.titre_en) ? s.titre_en : (s.titre || ''); }\n  function detailsSession(P, s, lang) {\n    const l = lab(lang), iso = isoDate(s.date);\n    const h = s.heure_debut ? (s.heure_fin ? `${s.heure_debut} – ${s.heure_fin}` : s.heure_debut) : '';\n    return box(P, `<div style=\"font-size:18px;font-weight:700;margin-bottom:8px\">${esc(sessionTitle(s, lang))}</div>` + rowsTable([\n      [l.date, esc(longDate(iso, lang))], [l.heure, esc(h)], [l.lieu, esc(s.lieu)],\n      [l.lien, s.lien_visio ? `<a href=\"${esc(s.lien_visio)}\" style=\"color:${P.couleur_principale}\">${esc(s.lien_visio)}</a>` : ''],\n      [l.intervenant, esc(s.intervenant)]\n    ]) + (s.infos_pratiques ? `<div style=\"margin-top:10px\">${esc(s.infos_pratiques)}</div>` : ''));\n  }\n  // Coordonnées d'un contact : sans libellés, donc lisible dans toutes les langues\n  function detailsContact(P, c) {\n    const lines = [\n      `<div style=\"font-size:18px;font-weight:700\">${esc(`${c.prenom || ''} ${c.nom || ''}`.trim())}</div>`,\n      [c.poste, c.entreprise].filter(Boolean).length ? `<div>${esc([c.poste, c.entreprise].filter(Boolean).join(' · '))}</div>` : '',\n      c.email ? `<div>✉️ <a dir=\"ltr\" href=\"mailto:${esc(c.email)}\" style=\"color:${P.couleur_principale};unicode-bidi:isolate\">${esc(c.email)}</a></div>` : '',\n      c.telephone ? `<div>📞 <a dir=\"ltr\" href=\"tel:${esc(String(c.telephone).replace(/\\s/g, ''))}\" style=\"color:${P.couleur_principale};unicode-bidi:isolate\">${esc(c.telephone)}</a></div>` : '',\n      c.ville ? `<div>📍 ${esc(c.ville)}</div>` : ''\n    ];\n    return box(P, lines.join(''));\n  }\n  function libelles(listes, type, codes, lang) {\n    const m = {}; for (const r of listes || []) if (norm(r.type) === type) m[norm(r.code)] = (norm(lang) === 'en' && r.libelle_en) ? r.libelle_en : (r.libelle_fr || r.code);\n    return list(codes).map(c => m[norm(c)] || c).join(', ');\n  }\n  function detailsDemandeur(P, d, lang, listes, withContact) {\n    const l = lab(lang);\n    return box(P, `<div style=\"font-size:18px;font-weight:700;margin-bottom:8px\">${esc(`${d.prenom || ''} ${d.nom || ''}`.trim())}</div>` + rowsTable([\n      [l.metiers, esc(libelles(listes, 'metier', d.metiers, lang))], [l.langues, esc(libelles(listes, 'langue', d.langues, lang))],\n      [l.ville, esc(d.ville)], [l.parcours, esc(d.parcours)],\n      [l.email, withContact && d.email ? `<a href=\"mailto:${esc(d.email)}\" style=\"color:${P.couleur_principale}\">${esc(d.email)}</a>` : ''],\n      [l.tel, withContact ? esc(d.telephone) : '']\n    ]));\n  }\n\n  // ---------- Page de réponse (après un clic dans un email) ----------\n  function page(P, o) {\n    const c = P.couleur_principale, ink = P.couleur_encre;\n    const tone = { ok: '#2E7D5B', warn: '#B7791F', err: '#B23A2E' }[o.tone || 'ok'];\n    const rtl = RTL.includes(norm(o.lang));\n    return `<!doctype html><html lang=\"${esc(o.lang || 'fr')}\" dir=\"${rtl ? 'rtl' : 'ltr'}\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>${esc(o.title)} – ${esc(P.nom_asso)}</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&family=Bricolage+Grotesque:opsz,wght@12..96,600;12..96,800&display=swap\" rel=\"stylesheet\">\n<style>body{margin:0;min-height:100vh;display:flex;flex-direction:column;background:#EEF2F2;font-family:'Atkinson Hyperlegible',Arial,sans-serif;color:${ink}}\nheader{padding:18px 24px;background:#fff;border-bottom:4px solid ${c}}header img{height:40px}\nmain{flex:1;display:flex;align-items:center;justify-content:center;padding:32px 16px}\n.card{background:#fff;border-radius:18px;max-width:520px;width:100%;padding:36px 32px;box-shadow:0 1px 0 rgba(18,52,59,.06),0 12px 32px -18px rgba(18,52,59,.35)}\n.mark{width:52px;height:52px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:${tone}1A;color:${tone};font-size:26px;font-weight:700}\nh1{font-family:'Bricolage Grotesque',Arial,sans-serif;font-weight:800;font-size:28px;line-height:1.15;margin:18px 0 10px}\np{font-size:17px;line-height:1.6;margin:0 0 12px}a.btn{display:inline-block;margin-top:10px;padding:12px 20px;border-radius:999px;background:${c};color:#fff;text-decoration:none;font-weight:700}\nfooter{padding:18px;text-align:center;font-size:14px;color:#4A6266}</style></head>\n<body><header><a href=\"${esc(P.site_url)}\"><img src=\"${esc(P.logo_url)}\" alt=\"${esc(P.nom_asso)}\"></a></header>\n<main><div class=\"card\"><div class=\"mark\">${o.tone === 'err' ? '!' : o.tone === 'warn' ? 'i' : '✓'}</div><h1>${esc(o.title)}</h1>${(o.paras || []).map(p => `<p>${esc(p)}</p>`).join('')}${o.cta ? `<a class=\"btn\" href=\"${esc(o.cta.url)}\">${esc(o.cta.label)}</a>` : ''}</div></main>\n<footer>${esc(P.slogan)} · ${esc(P.nom_asso)}</footer></body></html>`;\n  }\n\n  return { DEFAULTS, RTL, esc, list, norm, uid, token, params, link, isoDate, todayParis, nowParis, daysBetween, longDate, mix,\n    renderText, fill, pick, layout, email, button, box, detailsSession, detailsContact, detailsDemandeur, libelles, sessionTitle, page };\n})();\n</script>\n<script>// Liste déroulante à choix multiples (accessible au clavier)\nfunction MultiSelect(root, opts) {\n  let selected = [];\n  let active = -1;\n  const o = Object.assign({ placeholder: 'Choisir…', search: 'Rechercher…', empty: 'Aucun résultat', remove: 'Retirer', max: 0 }, opts);\n  const uidN = 'ms' + Math.random().toString(36).slice(2, 8);\n  root.classList.add('ms'); root.setAttribute('aria-expanded', 'false');\n  root.innerHTML = `<div class=\"ms-trigger\" role=\"combobox\" tabindex=\"0\" aria-haspopup=\"listbox\" aria-controls=\"${uidN}-list\" ${o.labelledby ? `aria-labelledby=\"${o.labelledby}\"` : ''}></div>\n    <div class=\"ms-panel\"><input class=\"ms-search\" type=\"search\" autocomplete=\"off\" placeholder=\"${o.search}\" aria-label=\"${o.search}\"><ul class=\"ms-list\" id=\"${uidN}-list\" role=\"listbox\" aria-multiselectable=\"true\"></ul></div>`;\n  const trigger = root.querySelector('.ms-trigger'), panel = root.querySelector('.ms-panel');\n  const search = root.querySelector('.ms-search'), listEl = root.querySelector('.ms-list');\n  const esc = s => String(s ?? '').replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n  const label = v => (o.options.find(x => x.value === v) || { label: v }).label;\n\n  function renderTrigger() {\n    trigger.innerHTML = selected.length\n      ? selected.map(v => `<span class=\"chip\">${esc(label(v))}<button type=\"button\" data-rm=\"${esc(v)}\" aria-label=\"${esc(o.remove)} ${esc(label(v))}\">×</button></span>`).join('')\n      : `<span class=\"ms-placeholder\">${esc(o.placeholder)}</span>`;\n  }\n  function visible() {\n    const q = search.value.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\n    return o.options.filter(x => !q || (x.label + ' ' + (x.natif || '') + ' ' + (x.group || '')).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').includes(q));\n  }\n  function renderList() {\n    const items = visible(); let html = '', g = null;\n    items.forEach((x, i) => {\n      if (x.group && x.group !== g) { g = x.group; html += `<li class=\"ms-group\" role=\"presentation\">${esc(g)}</li>`; }\n      const on = selected.includes(x.value);\n      html += `<li class=\"ms-opt${i === active ? ' active' : ''}\" role=\"option\" id=\"${uidN}-${i}\" aria-selected=\"${on}\" data-v=\"${esc(x.value)}\"><input type=\"checkbox\" tabindex=\"-1\" ${on ? 'checked' : ''}><span>${esc(x.label)}</span>${x.natif && x.natif !== x.label ? `<span class=\"natif\" lang=\"${esc(x.value)}\">${esc(x.natif)}</span>` : ''}</li>`;\n    });\n    listEl.innerHTML = html || `<li class=\"ms-empty\">${esc(o.empty)}</li>`;\n    if (active >= 0) { trigger.setAttribute('aria-activedescendant', `${uidN}-${active}`); const el = document.getElementById(`${uidN}-${active}`); el && el.scrollIntoView({ block: 'nearest' }); }\n  }\n  function toggle(v) {\n    if (selected.includes(v)) selected = selected.filter(x => x !== v);\n    else { if (o.max && selected.length >= o.max) return; selected.push(v); }\n    renderTrigger(); renderList(); o.onChange && o.onChange(selected.slice());\n  }\n  function open(focusSearch) {\n    if (root.getAttribute('aria-expanded') === 'true') return;\n    root.setAttribute('aria-expanded', 'true'); active = -1; search.value = ''; renderList();\n    if (focusSearch) setTimeout(() => search.focus(), 0);\n  }\n  function close(refocus) { root.setAttribute('aria-expanded', 'false'); if (refocus) trigger.focus(); }\n  trigger.addEventListener('click', e => {\n    const rm = e.target.closest('[data-rm]');\n    if (rm) { e.stopPropagation(); toggle(rm.dataset.rm); return; }\n    root.getAttribute('aria-expanded') === 'true' ? close() : open(true);\n  });\n  trigger.addEventListener('keydown', e => { if (['Enter', ' ', 'ArrowDown'].includes(e.key)) { e.preventDefault(); open(true); } });\n  search.addEventListener('input', () => { active = 0; renderList(); });\n  search.addEventListener('keydown', e => {\n    const n = visible().length;\n    if (e.key === 'ArrowDown') { e.preventDefault(); active = Math.min(n - 1, active + 1); renderList(); }\n    else if (e.key === 'ArrowUp') { e.preventDefault(); active = Math.max(0, active - 1); renderList(); }\n    else if (e.key === 'Enter') { e.preventDefault(); const x = visible()[active]; if (x) toggle(x.value); }\n    else if (e.key === 'Escape' || e.key === 'Tab') { close(e.key === 'Escape'); }\n  });\n  listEl.addEventListener('mousedown', e => e.preventDefault());\n  listEl.addEventListener('click', e => { const li = e.target.closest('[data-v]'); if (li) toggle(li.dataset.v); });\n  document.addEventListener('click', e => { if (e.target.isConnected && !root.contains(e.target)) close(); });\n  renderTrigger();\n  return {\n    get: () => selected.slice(),\n    set: vals => { selected = (vals || []).filter(v => o.options.some(x => x.value === v)); renderTrigger(); },\n    setOptions: (options, keep) => { o.options = options; selected = keep ? selected.filter(v => options.some(x => x.value === v)) : []; renderTrigger(); },\n    focus: () => trigger.focus()\n  };\n}\n</script>\n<script>\nconst D = /*__DATA__*/null;\nconst $ = s => document.querySelector(s);\nconst esc = TW.esc, norm = TW.norm;\nconst SHEETS = ['Parametres', 'Listes', 'Templates', 'Sessions', 'Inscriptions', 'Demandeurs', 'Contacts', 'MisesEnRelation'];\nlet S = {}, P = TW.params([]), auth = null, route = 'dashboard', chartMode = 'avenir';\nconst today = TW.todayParis();\n\n// ---------- Identité visuelle ----------\nfunction brand(p) {\n  document.documentElement.style.setProperty('--orange', p.couleur_principale);\n  document.documentElement.style.setProperty('--ink', p.couleur_encre);\n  for (const id of ['lg-logo', 'ap-logo', 'mt-logo']) { const i = document.getElementById(id); i.src = p.logo_url; i.alt = p.nom_asso; }\n  $('#lg-slogan').textContent = p.slogan;\n  document.title = 'Espace gestion – ' + p.nom_asso;\n}\nbrand(Object.assign(TW.params([]), D.P || {}));\n\n// ---------- API ----------\nasync function api(action, payload) {\n  $('#loading').style.display = 'block';\n  try {\n    const r = await fetch(D.api, { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-TW-Auth': auth }, body: JSON.stringify(Object.assign({ action }, payload || {})) });\n    if (r.status === 401 || r.status === 403) { const e = new Error('auth'); e.auth = true; throw e; }\n    const res = await r.json().catch(() => ({ ok: false, message: 'Réponse illisible du serveur.' }));\n    if (!r.ok || res.ok === false) throw new Error(res.message || `Erreur ${r.status}`);\n    return res;\n  } finally { $('#loading').style.display = 'none'; }\n}\nasync function load() {\n  const res = await api('load');\n  for (const s of SHEETS) S[s] = (res.data[s] || []).filter(r => r && Object.values(r).some(v => v !== '' && v !== null && v !== undefined));\n  P = TW.params(S.Parametres); brand(P);\n}\nasync function save(sheet, row, msg) {\n  const res = await api('save', { sheet, row });\n  const i = S[sheet].findIndex(r => String(r.id) === String(res.row.id));\n  if (i >= 0) S[sheet][i] = Object.assign({}, S[sheet][i], res.row); else S[sheet].push(res.row);\n  if (sheet === 'Parametres') { P = TW.params(S.Parametres); brand(P); }\n  if (msg !== false) toast(msg || 'Modifications enregistrées');\n  return res.row;\n}\nasync function remove(sheet, id, msg) {\n  await api('delete', { sheet, id });\n  S[sheet] = S[sheet].filter(r => String(r.id) !== String(id));\n  toast(msg || 'Supprimé');\n}\nfunction toast(msg, err) { const el = $('#toast'); el.textContent = msg; el.className = 'toast show' + (err ? ' err' : ''); clearTimeout(toast.t); toast.t = setTimeout(() => el.className = 'toast', 3800); }\nasync function guard(fn) { try { return await fn(); } catch (e) { if (e.auth) { logout(); toast('Session expirée : reconnectez-vous.', true); } else toast(e.message || 'Une erreur est survenue.', true); throw e; } }\n\n// ---------- Connexion ----------\n$('#lf').addEventListener('submit', async e => {\n  e.preventDefault();\n  const u = $('#lu').value.trim(), p = $('#lp').value;\n  if (!u || !p) { lerr('Saisissez votre identifiant et votre mot de passe.'); return; }\n  auth = u + ':' + p;\n  $('#lbtn').disabled = true; $('#lbtn').textContent = 'Connexion…';\n  try { await load(); try { sessionStorage.setItem('tw-auth', auth); sessionStorage.setItem('tw-user', u); } catch (_) {} start(u); }\n  catch (err) { auth = null; lerr(err.auth ? 'Identifiant ou mot de passe incorrect.' : \"Impossible de joindre le serveur. Vérifiez que le workflow « API gestionnaire » est actif.\"); }\n  finally { $('#lbtn').disabled = false; $('#lbtn').textContent = 'Se connecter'; }\n});\nfunction lerr(m) { const el = $('#lerr'); el.textContent = m; el.style.display = m ? 'block' : 'none'; }\nfunction start(u) { $('#login').style.display = 'none'; $('#app').classList.add('on'); $('#who').textContent = 'Connecté : ' + u; go(location.hash.slice(1) || 'dashboard'); }\nfunction logout() { auth = null; try { sessionStorage.removeItem('tw-auth'); } catch (_) {} $('#app').classList.remove('on'); $('#login').style.display = ''; closeDrawer(); }\n$('#logout').onclick = logout; $('#logout-m').onclick = logout;\n(async () => { let a = null, u = ''; try { a = sessionStorage.getItem('tw-auth'); u = sessionStorage.getItem('tw-user') || ''; } catch (_) {} if (a) { auth = a; try { await load(); start(u); } catch (e) { auth = null; } } })();\n\n// ---------- Navigation ----------\nconst ICONS = {\n  dashboard: '<path d=\"M3 13h8V3H3zM13 21h8V11h-8zM3 21h8v-6H3zM13 3v6h8V3z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/>',\n  demandes: '<circle cx=\"9\" cy=\"8\" r=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M2 21c0-4 3-6 7-6s7 2 7 6M17 8h5M19.5 5.5v5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>',\n  contacts: '<rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"9\" cy=\"11\" r=\"2.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M5.5 17c.6-2 2-3 3.5-3s2.9 1 3.5 3M15 10h3M15 14h3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>',\n  sessions: '<rect x=\"3\" y=\"5\" width=\"18\" height=\"16\" rx=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M3 10h18M8 3v4M16 3v4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>',\n  emails: '<rect x=\"3\" y=\"5\" width=\"18\" height=\"14\" rx=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"m4 7 8 6 8-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/>',\n  parametres: '<circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/>'\n};\nconst ROUTES = [['dashboard', 'Tableau de bord'], ['demandes', 'Demandes'], ['contacts', 'Contacts'], ['sessions', 'Formations et événements'], ['emails', 'Emails'], ['parametres', 'Paramètres']];\nconst SHORT = { dashboard: 'Accueil', demandes: 'Demandes', contacts: 'Contacts', sessions: 'Agenda', emails: 'Emails', parametres: 'Réglages' };\nfunction renderNav() {\n  const todo = S.MisesEnRelation.filter(m => m.statut === 'À valider').length;\n  $('#nav').innerHTML = ROUTES.map(([k, l]) => `<a href=\"#${k}\" data-r=\"${k}\" ${route === k ? 'aria-current=\"page\"' : ''}><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">${ICONS[k]}</svg><span class=\"lbl\">${l}</span><span class=\"short\" aria-hidden=\"true\">${SHORT[k]}</span>${k === 'demandes' && todo ? `<span class=\"count\" aria-label=\"${todo} à valider\">${todo}</span>` : ''}</a>`).join('');\n}\nwindow.addEventListener('hashchange', () => auth && go(location.hash.slice(1)));\nfunction go(r) { $('#tip').style.display = 'none'; route = ROUTES.some(x => x[0] === r) ? r : 'dashboard'; renderNav(); VIEWS[route](); $('#view').focus({ preventScroll: true }); window.scrollTo(0, 0); }\nconst refresh = () => { renderNav(); VIEWS[route](); };\n\n// ---------- Utilitaires d'affichage ----------\nconst listes = type => S.Listes.filter(l => norm(l.type) === type).sort((a, b) => (+a.ordre || 0) - (+b.ordre || 0));\nconst lib = (type, codes) => TW.libelles(S.Listes, type, codes, 'fr');\nconst fdate = (v, o) => { const iso = TW.isoDate(v); if (!iso) return ''; return new Intl.DateTimeFormat('fr-FR', Object.assign({ day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }, o)).format(new Date(iso + 'T12:00:00Z')); };\nconst fullName = r => `${r.prenom || ''} ${r.nom || ''}`.trim();\nconst BADGE = {\n  'Nouveau': 'b-new', 'Proposé': 'b-warn', 'À traiter manuellement': 'b-err', 'Mis en relation': 'b-ok', 'En emploi': 'b-ok', 'Archivé': 'b-off',\n  'À valider': 'b-new', 'En attente du contact': 'b-warn', 'Envoyée': 'b-ok', 'Refusée': 'b-off', 'Refusée par le contact': 'b-err',\n  'Inscrit': 'b-warn', 'Confirmé': 'b-ok', 'Annulé': 'b-off', 'Présent': 'b-ok', 'Absent': 'b-err'\n};\nconst badge = s => `<span class=\"badge ${BADGE[s] || ''}\">${esc(s || '—')}</span>`;\nconst sessionStats = s => {\n  const ins = S.Inscriptions.filter(i => String(i.session_id) === String(s.id));\n  const c = ins.filter(i => ['Confirmé', 'Présent'].includes(i.statut)).length;\n  const a = ins.filter(i => !i.statut || i.statut === 'Inscrit').length;\n  const x = ins.filter(i => ['Annulé', 'Absent'].includes(i.statut)).length;\n  return { ins, c, a, x, actifs: c + a, places: +s.places || 0 };\n};\nconst stitle = s => s.titre || s.titre_en || s.id;\nconst yes = v => norm(v) === 'oui';\n\n// ---------- Tiroir & formulaires ----------\nlet drawerState = null;\nfunction openDrawer({ title, sub, body, foot, onOpen }) {\n  $('#d-title').textContent = title; $('#d-sub').textContent = sub || '';\n  $('#d-body').innerHTML = body; $('#d-foot').innerHTML = foot || '';\n  $('#d-foot').style.display = foot ? '' : 'none';\n  $('#drawer').classList.add('open'); $('#dbg').classList.add('open');\n  drawerState = { last: document.activeElement }; onOpen && onOpen();\n  setTimeout(() => { const f = $('#d-body').querySelector('input:not([type=hidden]),select,textarea,button'); (f || $('#d-x')).focus(); }, 60);\n}\nfunction closeDrawer() { $('#drawer').classList.remove('open'); $('#dbg').classList.remove('open'); if (drawerState && drawerState.last) drawerState.last.focus && drawerState.last.focus(); drawerState = null; }\n$('#d-x').onclick = closeDrawer; $('#dbg').onclick = closeDrawer;\ndocument.addEventListener('keydown', e => { if (e.key === 'Escape' && drawerState && !document.querySelector('.ms[aria-expanded=true]')) closeDrawer(); });\n\n// Champs : {k, label, type, options, hint, req, full}\nfunction fieldsHtml(fields, row) {\n  const v = k => row[k] ?? '';\n  return '<div class=\"grid-2\">' + fields.map(f => {\n    const id = 'fx-' + f.k, span = f.full || ['textarea', 'multi', 'toggle'].includes(f.type) ? ' style=\"grid-column:1/-1\"' : '';\n    const lab = `<label for=\"${id}\">${esc(f.label)}${f.req ? ' <span class=\"req\">*</span>' : ''}</label>${f.hint ? `<span class=\"hint\">${esc(f.hint)}</span>` : ''}`;\n    let input;\n    if (f.type === 'textarea') input = `<textarea class=\"textarea\" id=\"${id}\" name=\"${f.k}\">${esc(v(f.k))}</textarea>`;\n    else if (f.type === 'select') input = `<select class=\"select\" id=\"${id}\" name=\"${f.k}\">${f.options.map(o => { const [val, l] = Array.isArray(o) ? o : [o, o]; return `<option value=\"${esc(val)}\" ${String(v(f.k)) === String(val) ? 'selected' : ''}>${esc(l)}</option>`; }).join('')}</select>`;\n    else if (f.type === 'multi') return `<div class=\"field\" data-multi=\"${f.k}\"${span}><span class=\"label\" id=\"${id}-l\">${esc(f.label)}${f.req ? ' <span class=\"req\">*</span>' : ''}</span>${f.hint ? `<span class=\"hint\">${esc(f.hint)}</span>` : ''}<div id=\"${id}\"></div><span class=\"err-msg\">Choisissez au moins une option.</span></div>`;\n    else if (f.type === 'toggle') return `<div class=\"field\"${span}><label class=\"switch\"><input type=\"checkbox\" role=\"switch\" name=\"${f.k}\" ${yes(v(f.k)) ? 'checked' : ''}><span><b>${esc(f.label)}</b><span>${esc(f.hint || '')}</span></span></label></div>`;\n    else if (f.type === 'color') input = `<div class=\"color-in\"><input type=\"color\" value=\"${esc(v(f.k) || '#F26716')}\" data-mirror=\"${id}\" aria-label=\"${esc(f.label)} (sélecteur)\"><input class=\"input\" id=\"${id}\" name=\"${f.k}\" value=\"${esc(v(f.k))}\" maxlength=\"7\"></div>`;\n    else input = `<input class=\"input\" id=\"${id}\" name=\"${f.k}\" type=\"${f.type || 'text'}\" value=\"${esc(f.type === 'date' ? TW.isoDate(v(f.k)) : v(f.k))}\" ${f.min !== undefined ? `min=\"${f.min}\"` : ''}>`;\n    return `<div class=\"field\"${span}>${lab}${input}<span class=\"err-msg\">${f.type === 'email' ? 'Adresse email invalide.' : 'Ce champ est obligatoire.'}</span></div>`;\n  }).join('') + '</div>';\n}\nfunction mountMulti(fields, row, scope) {\n  const ms = {};\n  for (const f of fields.filter(f => f.type === 'multi')) {\n    const el = scope.querySelector('#fx-' + f.k);\n    ms[f.k] = MultiSelect(el, { labelledby: 'fx-' + f.k + '-l', options: f.options(), placeholder: 'Choisir…', search: 'Rechercher…', empty: 'Aucun résultat', remove: 'Retirer' });\n    ms[f.k].set(TW.list(row[f.k]));\n  }\n  scope.querySelectorAll('[data-mirror]').forEach(c => { const t = scope.querySelector('#' + c.dataset.mirror); c.oninput = () => t.value = c.value.toUpperCase(); t.oninput = () => { if (/^#[0-9a-f]{6}$/i.test(t.value)) c.value = t.value; }; });\n  return ms;\n}\nfunction readFields(fields, scope, ms) {\n  const out = {}; let ok = true, first = null;\n  for (const f of fields) {\n    let val;\n    if (f.type === 'multi') val = ms[f.k].get().join(',');\n    else if (f.type === 'toggle') val = scope.querySelector(`[name=\"${f.k}\"]`).checked ? 'Oui' : 'Non';\n    else val = scope.querySelector(`[name=\"${f.k}\"]`).value.trim();\n    if (f.type === 'number' && val !== '') val = Number(val);\n    out[f.k] = val;\n    const bad = (f.req && (val === '' || val === null)) || (f.type === 'email' && val && !/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(val));\n    const fe = f.type === 'multi' ? scope.querySelector(`[data-multi=\"${f.k}\"]`) : scope.querySelector(`[name=\"${f.k}\"]`)?.closest('.field');\n    fe && fe.classList.toggle('invalid', !!bad);\n    if (bad) { ok = false; first = first || fe; }\n  }\n  if (!ok) { first.querySelector('input,select,textarea,.ms-trigger')?.focus(); toast('Quelques champs sont à compléter.', true); }\n  return ok ? out : null;\n}\nfunction formDrawer({ title, sub, fields, row, sheet, onSaved, extraFoot, del, delMsg, saveLabel }) {\n  openDrawer({ title, sub, body: `<form id=\"dform\" novalidate>${fieldsHtml(fields, row)}</form>`,\n    foot: `${del ? '<button class=\"btn btn-danger\" type=\"button\" id=\"d-del\">Supprimer</button>' : ''}${extraFoot || ''}<div class=\"r\"><button class=\"btn btn-ghost\" type=\"button\" id=\"d-cancel\">Annuler</button><button class=\"btn btn-primary\" type=\"button\" id=\"d-save\">${saveLabel || 'Enregistrer'}</button></div>`,\n    onOpen: () => {\n      const scope = $('#d-body'), ms = mountMulti(fields, row, scope);\n      $('#d-cancel').onclick = closeDrawer;\n      const doSave = async () => { const vals = readFields(fields, scope, ms); if (!vals) return; $('#d-save').disabled = true;\n        try { const saved = await guard(() => save(sheet, Object.assign({}, row, vals))); closeDrawer(); onSaved && onSaved(saved); refresh(); } catch (_) { $('#d-save').disabled = false; } };\n      $('#d-save').onclick = doSave; $('#dform').onsubmit = e => { e.preventDefault(); doSave(); };\n      if (del) $('#d-del').onclick = async () => { if (!confirm(delMsg || 'Supprimer définitivement cet élément ?')) return; try { await guard(() => remove(sheet, row.id)); closeDrawer(); refresh(); } catch (_) {} };\n    } });\n}\n\n// =====================================================================\nconst VIEWS = {};\n\n// ---------- Tableau de bord ----------\nVIEWS.dashboard = () => {\n  const dem = S.Demandeurs, mer = S.MisesEnRelation;\n  const enCours = dem.filter(d => ['Nouveau', 'Proposé', 'À traiter manuellement'].includes(d.statut)).length;\n  const month = today.slice(0, 7);\n  const envoyees = mer.filter(m => m.statut === 'Envoyée'), envMois = envoyees.filter(m => String(m.date_decision || m.date).slice(0, 7) === month).length;\n  const futures = S.Sessions.filter(s => TW.isoDate(s.date) >= today);\n  let insFut = 0, conf = 0, att = 0;\n  for (const s of futures) { const st = sessionStats(s); insFut += st.actifs; conf += st.c; att += st.a; }\n  const taux = insFut ? Math.round(100 * conf / insFut) : null;\n  const aValider = mer.filter(m => m.statut === 'À valider');\n  const manuels = dem.filter(d => d.statut === 'À traiter manuellement');\n  $('#view').innerHTML = `\n  <div class=\"head\"><div><h1>Tableau de bord</h1><p>${esc(new Intl.DateTimeFormat('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date()))}</p></div>\n    <div class=\"tools\"><button class=\"btn btn-ghost btn-sm\" id=\"reload\" type=\"button\">Actualiser les données</button></div></div>\n  <div class=\"kpis\">\n    <div class=\"kpi\"><b>${enCours}</b><span>Demandes en cours</span><small>${aValider.length} proposition${aValider.length > 1 ? 's' : ''} à valider</small></div>\n    <div class=\"kpi\"><b>${envoyees.length}</b><span>Mises en relation</span><small>dont ${envMois} ce mois-ci</small></div>\n    <div class=\"kpi\"><b>${insFut}</b><span>Inscriptions à venir</span><small>sur ${futures.length} session${futures.length > 1 ? 's' : ''} programmée${futures.length > 1 ? 's' : ''}</small></div>\n    <div class=\"kpi\"><b>${taux === null ? '–' : taux + ' %'}</b><span>Présences confirmées</span><small>${conf} confirmée${conf > 1 ? 's' : ''}, ${att} sans réponse</small></div>\n  </div>\n  <div class=\"panel\">\n    <div class=\"head\" style=\"margin-bottom:10px\"><div><h2>Inscriptions par formation et événement</h2><p class=\"sub\" style=\"margin:0\">Le trait vertical marque le nombre de places.</p></div>\n      <div class=\"tools\"><div class=\"seg-toggle\" role=\"group\" aria-label=\"Période\">${[['avenir', 'À venir'], ['passees', 'Passées'], ['toutes', 'Toutes']].map(([k, l]) => `<button type=\"button\" data-cm=\"${k}\" aria-pressed=\"${chartMode === k}\">${l}</button>`).join('')}</div>\n      <button class=\"btn btn-ghost btn-sm\" type=\"button\" id=\"tbl-toggle\" aria-pressed=\"false\">Voir en tableau</button></div></div>\n    <div class=\"legend\"><span><i class=\"sw-c\"></i>Présence confirmée</span><span><i class=\"sw-a\"></i>Inscrit, sans réponse</span><span><i class=\"sw-x\"></i>Annulé ou absent</span></div>\n    <div id=\"chart\"></div>\n  </div>\n  <div class=\"cols\">\n    <div class=\"panel\"><h2>À traiter</h2><p class=\"sub\">Propositions de mise en relation en attente de votre décision.</p>\n      ${aValider.length ? `<ul class=\"todo\">${aValider.slice(0, 8).map(m => `<li><div class=\"who\"><b>${esc(m.demandeur_nom)} → ${esc(m.contact_nom)}</b><span>Score ${esc(m.score)} · ${esc(m.raisons)}</span></div><div class=\"acts\"><button class=\"btn btn-primary btn-sm\" data-mer=\"${esc(m.token)}\" data-a=\"valider\">Valider</button><button class=\"btn btn-ghost btn-sm\" data-mer=\"${esc(m.token)}\" data-a=\"refuser\">Refuser</button></div></li>`).join('')}</ul>${aValider.length > 8 ? `<p><a href=\"#demandes\">Voir les ${aValider.length} propositions</a></p>` : ''}` : '<p class=\"sub\" style=\"margin:0\">Rien à valider pour le moment.</p>'}\n      ${manuels.length ? `<h3 style=\"font-size:17px;margin:18px 0 8px\">Sans contact trouvé (${manuels.length})</h3><ul class=\"todo\">${manuels.slice(0, 5).map(d => `<li><div class=\"who\"><b>${esc(fullName(d))}</b><span>${esc(lib('metier', d.metiers))}</span></div><button class=\"btn btn-ghost btn-sm\" data-dem=\"${esc(d.id)}\">Ouvrir</button></li>`).join('')}</ul>` : ''}\n    </div>\n    <div class=\"panel\"><h2>Avancement des demandes</h2><p class=\"sub\">Toutes les demandes reçues, par étape.</p>\n      <div class=\"pipe\">${['Nouveau', 'Proposé', 'Mis en relation', 'En emploi'].map(st => `<div class=\"step ${st === 'Nouveau' ? 'hot' : st === 'En emploi' ? 'good' : ''}\"><b>${dem.filter(d => d.statut === st).length}</b><span>${st}</span></div>`).join('')}</div>\n      <div class=\"side-stats\"><span><b>${manuels.length}</b> à traiter manuellement</span><span><b>${dem.filter(d => d.statut === 'Archivé').length}</b> archivées</span></div>\n      <h3 style=\"font-size:17px;margin:22px 0 10px\">Mises en relation</h3>\n      <div class=\"pipe\">${['À valider', 'En attente du contact', 'Envoyée'].map(st => `<div class=\"step ${st === 'Envoyée' ? 'good' : ''}\"><b>${mer.filter(m => m.statut === st).length}</b><span>${st}</span></div>`).join('')}</div>\n      <div class=\"side-stats\"><span><b>${mer.filter(m => m.statut === 'Refusée').length}</b> refusées par vous</span><span><b>${mer.filter(m => m.statut === 'Refusée par le contact').length}</b> refusées par le contact</span></div>\n    </div>\n  </div>`;\n  drawChart(false);\n  $('#reload').onclick = () => guard(load).then(() => { refresh(); toast('Données actualisées'); });\n  document.querySelectorAll('[data-cm]').forEach(b => b.onclick = () => { chartMode = b.dataset.cm; document.querySelectorAll('[data-cm]').forEach(x => x.setAttribute('aria-pressed', x === b)); drawChart($('#tbl-toggle').getAttribute('aria-pressed') === 'true'); });\n  $('#tbl-toggle').onclick = e => { const on = e.currentTarget.getAttribute('aria-pressed') !== 'true'; e.currentTarget.setAttribute('aria-pressed', on); e.currentTarget.textContent = on ? 'Voir le graphique' : 'Voir en tableau'; drawChart(on); };\n  bindMerButtons($('#view')); document.querySelectorAll('[data-dem]').forEach(b => b.onclick = () => openDemande(S.Demandeurs.find(d => d.id === b.dataset.dem)));\n};\nfunction drawChart(asTable) {\n  $('#tip').style.display = 'none';\n  let ss = S.Sessions.map(s => Object.assign({ iso: TW.isoDate(s.date) }, s));\n  if (chartMode === 'avenir') ss = ss.filter(s => s.iso >= today).sort((a, b) => a.iso.localeCompare(b.iso));\n  else if (chartMode === 'passees') ss = ss.filter(s => s.iso < today).sort((a, b) => b.iso.localeCompare(a.iso)).slice(0, 12);\n  else ss = ss.sort((a, b) => b.iso.localeCompare(a.iso)).slice(0, 20);\n  const el = $('#chart');\n  if (!ss.length) { el.innerHTML = `<p class=\"sub\">Aucune session ${chartMode === 'avenir' ? 'programmée' : chartMode === 'passees' ? 'passée' : ''}. <a href=\"#sessions\">Créer une formation ou un événement</a></p>`; return; }\n  const rows = ss.map(s => Object.assign({ s }, sessionStats(s)));\n  if (asTable) {\n    el.innerHTML = `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>Session</th><th>Date</th><th class=\"num\">Confirmés</th><th class=\"num\">Sans réponse</th><th class=\"num\">Annulés / absents</th><th class=\"num\">Places</th></tr></thead><tbody>${rows.map(r => `<tr><td data-l=\"Session\">${esc(stitle(r.s))}</td><td data-l=\"Date\">${fdate(r.s.date)}</td><td class=\"num\" data-l=\"Confirmés\">${r.c}</td><td class=\"num\" data-l=\"Sans réponse\">${r.a}</td><td class=\"num\" data-l=\"Annulés\">${r.x}</td><td class=\"num\" data-l=\"Places\">${r.places || '–'}</td></tr>`).join('')}</tbody></table></div>`;\n    return;\n  }\n  const max = Math.max(1, ...rows.map(r => Math.max(r.c + r.a + r.x, r.places)));\n  const step = max <= 10 ? 2 : max <= 25 ? 5 : max <= 60 ? 10 : 20, top = Math.ceil(max / step) * step;\n  const pct = n => (100 * n / top);\n  el.innerHTML = `<div class=\"bars\">${rows.map((r, i) => `<div class=\"bar-row\"><div class=\"bar-label\"><b>${esc(stitle(r.s))}</b><span>${esc(r.s.type || '')} · ${fdate(r.s.date, { year: undefined })}</span></div>\n    <div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:calc(${pct(r.c + r.a + r.x)}% + ${[r.c, r.a, r.x].filter(Boolean).length > 1 ? ([r.c, r.a, r.x].filter(Boolean).length - 1) * 2 : 0}px)\">\n      ${r.c ? `<div class=\"seg c\" style=\"flex:${r.c}\" data-tip=\"${i}|c\"></div>` : ''}${r.a ? `<div class=\"seg a\" style=\"flex:${r.a}\" data-tip=\"${i}|a\"></div>` : ''}${r.x ? `<div class=\"seg x\" style=\"flex:${r.x}\" data-tip=\"${i}|x\"></div>` : ''}</div>\n      ${r.places ? `<div class=\"cap\" style=\"left:${pct(r.places)}%\" data-tip=\"${i}|p\"></div>` : ''}\n      <span class=\"bar-val\" style=\"left:calc(${pct(Math.max(r.c + r.a + r.x, r.places))}% + ${r.c + r.a + r.x ? 10 : 0}px)\">${r.actifs}${r.places ? ' / ' + r.places : ''}</span></div></div>`).join('')}</div>\n    <div class=\"axis\"><div></div><div class=\"ticks\">${Array.from({ length: top / step + 1 }, (_, k) => `<span style=\"left:${pct(k * step)}%\">${k * step}</span>`).join('')}</div></div>`;\n  const tip = $('#tip');\n  el.querySelectorAll('[data-tip]').forEach(seg => {\n    seg.addEventListener('mousemove', e => {\n      const [i, k] = seg.dataset.tip.split('|'), r = rows[+i];\n      const label = { c: ['Présence confirmée', r.c], a: ['Inscrit, sans réponse', r.a], x: ['Annulé ou absent', r.x], p: ['Places', r.places] }[k];\n      tip.innerHTML = `<b>${esc(stitle(r.s))}</b><br>${label[0]} : ${label[1]}<br><span style=\"opacity:.8\">${r.actifs} inscrit${r.actifs > 1 ? 's' : ''} actif${r.actifs > 1 ? 's' : ''}${r.places ? ' sur ' + r.places + ' places' : ''}</span>`;\n      tip.style.display = 'block'; tip.style.left = Math.min(e.clientX + 14, innerWidth - 270) + 'px'; tip.style.top = (e.clientY + 14) + 'px';\n    });\n    seg.addEventListener('mouseleave', () => tip.style.display = 'none');\n  });\n}\nfunction bindMerButtons(scope) {\n  scope.querySelectorAll('[data-mer]').forEach(b => b.onclick = async () => {\n    b.disabled = true;\n    try {\n      const r = await fetch(`${D.mer}?t=${encodeURIComponent(b.dataset.mer)}&a=${b.dataset.a}&format=json`);\n      const res = await r.json();\n      toast(res.message || (res.ok ? 'Enregistré' : 'Action impossible'), !res.ok);\n      await guard(load); closeDrawer(); refresh();\n    } catch (e) { toast(\"L'action n'a pas abouti. Vérifiez que le workflow « Décisions » est actif.\", true); b.disabled = false; }\n  });\n}\n\n// ---------- Demandes ----------\nlet demFilter = { q: '', statut: 'actives' };\nVIEWS.demandes = () => {\n  const statuts = ['Nouveau', 'Proposé', 'À traiter manuellement', 'Mis en relation', 'En emploi', 'Archivé'];\n  $('#view').innerHTML = `<div class=\"head\"><div><h1>Demandes de mise en relation</h1><p>Reçues via le formulaire public. Cliquez sur une ligne pour la traiter.</p></div><div class=\"tools\"><a class=\"btn btn-ghost btn-sm\" href=\"${esc(D.demande)}\" target=\"_blank\" rel=\"noopener\">Ouvrir le formulaire public</a></div></div>\n    <div class=\"toolbar\"><input class=\"input\" type=\"search\" id=\"dq\" placeholder=\"Rechercher un nom, un email, un métier…\" aria-label=\"Rechercher\" value=\"${esc(demFilter.q)}\">\n    <select class=\"select\" id=\"ds\" aria-label=\"Filtrer par statut\"><option value=\"actives\">Demandes en cours</option><option value=\"\">Tous les statuts</option>${statuts.map(s => `<option ${demFilter.statut === s ? 'selected' : ''}>${s}</option>`).join('')}</select></div><div id=\"dlist\"></div>`;\n  $('#ds').value = demFilter.statut;\n  const draw = () => {\n    const q = norm(demFilter.q);\n    let rows = S.Demandeurs.slice().sort((a, b) => String(TW.isoDate(b.date_demande)).localeCompare(TW.isoDate(a.date_demande)));\n    if (demFilter.statut === 'actives') rows = rows.filter(d => ['Nouveau', 'Proposé', 'À traiter manuellement'].includes(d.statut));\n    else if (demFilter.statut) rows = rows.filter(d => d.statut === demFilter.statut);\n    if (q) rows = rows.filter(d => norm([fullName(d), d.email, d.ville, lib('metier', d.metiers), lib('langue', d.langues)].join(' ')).includes(q));\n    $('#dlist').innerHTML = rows.length ? `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>Demandeur</th><th>Métiers recherchés</th><th>Langues</th><th>Reçue le</th><th>Statut</th><th class=\"num\">Propositions</th></tr></thead><tbody>${rows.map(d => {\n      const props = S.MisesEnRelation.filter(m => m.demandeur_id === d.id);\n      return `<tr class=\"click\" data-id=\"${esc(d.id)}\" tabindex=\"0\"><td data-l=\"Demandeur\"><b>${esc(fullName(d))}</b><div class=\"muted\">${esc(d.email)}${d.ville ? ' · ' + esc(d.ville) : ''}</div></td><td data-l=\"Métiers\">${esc(lib('metier', d.metiers))}</td><td data-l=\"Langues\">${esc(lib('langue', d.langues))}</td><td data-l=\"Reçue le\">${fdate(d.date_demande)}</td><td data-l=\"Statut\">${badge(d.statut)}</td><td class=\"num\" data-l=\"Propositions\">${props.length ? `${props.filter(m => m.statut === 'Envoyée').length} envoyée${props.filter(m => m.statut === 'Envoyée').length > 1 ? 's' : ''} / ${props.length}` : '–'}</td></tr>`; }).join('')}</tbody></table></div>`\n      : `<div class=\"empty\">${S.Demandeurs.length ? 'Aucune demande ne correspond à ces filtres.' : 'Aucune demande pour le moment. Partagez le lien du formulaire public pour en recevoir.'}</div>`;\n    $('#dlist').querySelectorAll('tr[data-id]').forEach(tr => { const open = () => openDemande(S.Demandeurs.find(d => d.id === tr.dataset.id)); tr.onclick = open; tr.onkeydown = e => { if (e.key === 'Enter') open(); }; });\n  };\n  $('#dq').oninput = e => { demFilter.q = e.target.value; draw(); };\n  $('#ds').onchange = e => { demFilter.statut = e.target.value; draw(); };\n  draw();\n};\nfunction openDemande(d) {\n  if (!d) return;\n  const props = S.MisesEnRelation.filter(m => m.demandeur_id === d.id).sort((a, b) => String(b.date).localeCompare(String(a.date)));\n  const statuts = ['Nouveau', 'Proposé', 'À traiter manuellement', 'Mis en relation', 'En emploi', 'Archivé'];\n  openDrawer({ title: fullName(d), sub: `Demande reçue le ${fdate(d.date_demande)}`,\n    body: `<dl class=\"dl\"><dt>Email</dt><dd><a href=\"mailto:${esc(d.email)}\">${esc(d.email)}</a></dd>${d.telephone ? `<dt>Téléphone</dt><dd>${esc(d.telephone)}</dd>` : ''}${d.ville ? `<dt>Ville</dt><dd>${esc(d.ville)}</dd>` : ''}\n      <dt>Langues</dt><dd>${esc(lib('langue', d.langues))}</dd><dt>Métiers</dt><dd>${esc(lib('metier', d.metiers))}</dd>${d.parcours ? `<dt>Parcours</dt><dd>${esc(d.parcours)}</dd>` : ''}</dl>\n      <div class=\"grid-2\"><div class=\"field\"><label for=\"dm-st\">Statut</label><select class=\"select\" id=\"dm-st\">${statuts.map(s => `<option ${d.statut === s ? 'selected' : ''}>${s}</option>`).join('')}</select><span class=\"hint\">Remettre sur « Nouveau » relance la recherche de contacts à la prochaine heure.</span></div></div>\n      <div class=\"field\"><label for=\"dm-notes\">Notes internes</label><textarea class=\"textarea\" id=\"dm-notes\">${esc(d.notes)}</textarea></div>\n      <h3 style=\"font-size:19px;margin:8px 0 12px\">Propositions de contacts</h3>\n      ${props.length ? `<ul class=\"props\">${props.map(m => { const c = S.Contacts.find(x => x.id === m.contact_id) || {}; return `<li><div class=\"top\"><b>${esc(m.contact_nom)}${c.entreprise ? ` <span class=\"muted\" style=\"font-weight:400\">· ${esc(c.entreprise)}</span>` : ''}</b>${badge(m.statut)}</div>\n        <div class=\"why\">Score ${esc(m.score)} · ${esc(m.raisons)}${c.id ? ` · ${yes(c.accord_partage) ? 'partage libre' : 'accord à demander'}` : ''}</div>${m.historique ? `<div class=\"why\">${esc(String(m.historique).split('\\n').slice(-1)[0])}</div>` : ''}\n        ${m.statut === 'À valider' ? `<div class=\"acts\"><button class=\"btn btn-primary btn-sm\" data-mer=\"${esc(m.token)}\" data-a=\"valider\">Valider</button><button class=\"btn btn-ghost btn-sm\" data-mer=\"${esc(m.token)}\" data-a=\"refuser\">Refuser</button></div>` : ''}</li>`; }).join('')}</ul>`\n        : `<p class=\"sub\">${d.statut === 'Nouveau' ? 'La recherche automatique tourne toutes les heures.' : 'Aucune proposition enregistrée.'}</p>`}`,\n    foot: `<button class=\"btn btn-danger\" type=\"button\" id=\"dm-del\">Supprimer</button><div class=\"r\"><button class=\"btn btn-ghost\" type=\"button\" id=\"dm-c\">Fermer</button><button class=\"btn btn-primary\" type=\"button\" id=\"dm-s\">Enregistrer</button></div>`,\n    onOpen: () => {\n      bindMerButtons($('#d-body'));\n      $('#dm-c').onclick = closeDrawer;\n      $('#dm-s').onclick = async () => { try { await guard(() => save('Demandeurs', Object.assign({}, d, { statut: $('#dm-st').value, notes: $('#dm-notes').value }))); closeDrawer(); refresh(); } catch (_) {} };\n      $('#dm-del').onclick = async () => { if (!confirm(`Supprimer la demande de ${fullName(d)} ? Ses données personnelles seront effacées.`)) return; try { await guard(() => remove('Demandeurs', d.id, 'Demande supprimée')); closeDrawer(); refresh(); } catch (_) {} };\n    } });\n}\n\n// ---------- Contacts ----------\nlet contactQ = '';\nconst CONTACT_FIELDS = () => [\n  { k: 'prenom', label: 'Prénom', req: true }, { k: 'nom', label: 'Nom', req: true },\n  { k: 'email', label: 'Email', type: 'email', req: true }, { k: 'telephone', label: 'Téléphone', type: 'tel' },\n  { k: 'entreprise', label: 'Entreprise ou structure' }, { k: 'poste', label: 'Poste' },\n  { k: 'ville', label: 'Ville' }, { k: 'langue_contact', label: 'Langue des emails envoyés au contact', type: 'select', options: [['fr', 'Français'], ['en', 'Anglais']] },\n  { k: 'metiers', label: 'Métiers sur lesquels il ou elle peut aider', type: 'multi', req: true, hint: 'Utilisés pour trouver les demandes correspondantes.', options: () => listes('metier').map(m => ({ value: m.code, label: m.libelle_fr, group: String(m.groupe || '').split('|')[0].trim() })) },\n  { k: 'langues', label: 'Langues parlées', type: 'multi', options: () => listes('langue').map(l => ({ value: l.code, label: l.libelle_fr, natif: l.libelle_natif })) },\n  { k: 'accord_partage', label: 'Accord pour partager ses coordonnées sans le consulter', type: 'toggle', hint: 'Désactivé : à chaque mise en relation validée, le contact reçoit un email pour accepter ou refuser avant que ses coordonnées soient transmises.' },\n  { k: 'disponible', label: 'Disponible pour de nouvelles mises en relation', type: 'toggle', hint: 'Désactivez pour mettre ce contact en pause.' },\n  { k: 'notes', label: 'Notes internes', type: 'textarea' }\n];\nVIEWS.contacts = () => {\n  $('#view').innerHTML = `<div class=\"head\"><div><h1>Contacts de l'association</h1><p>Les personnes de votre réseau qui acceptent d'aider les demandeurs.</p></div><div class=\"tools\"><button class=\"btn btn-primary\" id=\"c-add\" type=\"button\">Ajouter un contact</button></div></div>\n    <div class=\"toolbar\"><input class=\"input\" type=\"search\" id=\"cq\" placeholder=\"Rechercher un nom, une entreprise, un métier…\" aria-label=\"Rechercher\" value=\"${esc(contactQ)}\"></div><div id=\"clist\"></div>`;\n  const draw = () => {\n    const q = norm(contactQ);\n    const rows = S.Contacts.filter(c => !q || norm([fullName(c), c.email, c.entreprise, c.poste, c.ville, lib('metier', c.metiers)].join(' ')).includes(q)).sort((a, b) => fullName(a).localeCompare(fullName(b)));\n    $('#clist').innerHTML = rows.length ? `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>Contact</th><th>Métiers</th><th>Langues</th><th>Partage des coordonnées</th><th>Disponible</th><th class=\"num\">Mises en relation</th></tr></thead><tbody>${rows.map(c => `<tr class=\"click\" tabindex=\"0\" data-id=\"${esc(c.id)}\"><td data-l=\"Contact\"><b>${esc(fullName(c))}</b><div class=\"muted\">${esc([c.poste, c.entreprise].filter(Boolean).join(' · '))}</div></td><td data-l=\"Métiers\">${esc(lib('metier', c.metiers))}</td><td data-l=\"Langues\">${esc(lib('langue', c.langues))}</td><td data-l=\"Partage\">${yes(c.accord_partage) ? '<span class=\"badge b-ok\">Accord donné</span>' : '<span class=\"badge b-warn\">Accord à demander</span>'}</td><td data-l=\"Disponible\">${yes(c.disponible) ? 'Oui' : '<span class=\"muted\">En pause</span>'}</td><td class=\"num\" data-l=\"Mises en relation\">${+c.nb_mises_en_relation || 0}</td></tr>`).join('')}</tbody></table></div>`\n      : `<div class=\"empty\">${S.Contacts.length ? 'Aucun contact ne correspond.' : 'Aucun contact pour le moment. Ajoutez les membres de votre réseau qui peuvent aider.'}</div>`;\n    $('#clist').querySelectorAll('tr[data-id]').forEach(tr => { const open = () => editContact(S.Contacts.find(c => c.id === tr.dataset.id)); tr.onclick = open; tr.onkeydown = e => { if (e.key === 'Enter') open(); }; });\n  };\n  $('#cq').oninput = e => { contactQ = e.target.value; draw(); };\n  $('#c-add').onclick = () => editContact(null);\n  draw();\n};\nfunction editContact(c) {\n  const row = c || { langue_contact: 'fr', accord_partage: 'Non', disponible: 'Oui', nb_mises_en_relation: 0 };\n  formDrawer({ title: c ? fullName(c) : 'Nouveau contact', sub: c ? `${+c.nb_mises_en_relation || 0} mise(s) en relation` : '', fields: CONTACT_FIELDS(), row, sheet: 'Contacts', del: !!c, delMsg: `Supprimer ${c ? fullName(c) : ''} de vos contacts ?` });\n}\n\n// ---------- Formations et événements ----------\nlet sessFilter = 'avenir';\nconst SESSION_FIELDS = [\n  { k: 'type', label: 'Type', type: 'select', options: ['Formation', 'Événement'] }, { k: 'places', label: 'Nombre de places', type: 'number', hint: '0 = sans limite', min: 0 },\n  { k: 'titre', label: 'Titre (français)', req: true, full: true }, { k: 'titre_en', label: 'Titre (anglais)', full: true },\n  { k: 'date', label: 'Date', type: 'date', req: true }, { k: 'intervenant', label: 'Animé par' },\n  { k: 'heure_debut', label: 'Heure de début', type: 'time' }, { k: 'heure_fin', label: 'Heure de fin', type: 'time' },\n  { k: 'lieu', label: 'Lieu', full: true, hint: 'Adresse, ou « En ligne ».' }, { k: 'lien_visio', label: 'Lien de visioconférence', type: 'url', full: true },\n  { k: 'description', label: 'Description (français)', type: 'textarea' }, { k: 'description_en', label: 'Description (anglais)', type: 'textarea' },\n  { k: 'infos_pratiques', label: 'Infos pratiques (dans les emails)', type: 'textarea' },\n  { k: 'publie', label: \"Publié dans l'agenda public\", type: 'toggle', hint: 'Désactivé : la session reste en brouillon, personne ne peut s’inscrire.' }\n];\nVIEWS.sessions = () => {\n  $('#view').innerHTML = `<div class=\"head\"><div><h1>Formations et événements</h1><p>Créez les sessions, suivez les inscriptions et les confirmations de présence.</p></div><div class=\"tools\"><a class=\"btn btn-ghost btn-sm\" href=\"${esc(D.agenda)}\" target=\"_blank\" rel=\"noopener\">Voir l'agenda public</a><button class=\"btn btn-primary\" id=\"s-add\" type=\"button\">Nouvelle session</button></div></div>\n    <div class=\"toolbar\"><div class=\"seg-toggle\" role=\"group\" aria-label=\"Période\">${[['avenir', 'À venir'], ['passees', 'Passées'], ['toutes', 'Toutes']].map(([k, l]) => `<button type=\"button\" data-sf=\"${k}\" aria-pressed=\"${sessFilter === k}\">${l}</button>`).join('')}</div></div><div id=\"slist\"></div>`;\n  const draw = () => {\n    let rows = S.Sessions.map(s => Object.assign({ iso: TW.isoDate(s.date) }, s));\n    if (sessFilter === 'avenir') rows = rows.filter(s => s.iso >= today).sort((a, b) => a.iso.localeCompare(b.iso));\n    else if (sessFilter === 'passees') rows = rows.filter(s => s.iso < today).sort((a, b) => b.iso.localeCompare(a.iso));\n    else rows.sort((a, b) => b.iso.localeCompare(a.iso));\n    $('#slist').innerHTML = rows.length ? `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>Date</th><th>Session</th><th>Inscriptions</th><th>Confirmées</th><th>Agenda</th></tr></thead><tbody>${rows.map(s => { const st = sessionStats(s); return `<tr class=\"click\" tabindex=\"0\" data-id=\"${esc(s.id)}\"><td data-l=\"Date\"><b>${fdate(s.date)}</b><div class=\"muted\">${esc([s.heure_debut, s.heure_fin].filter(Boolean).join(' – '))}</div></td><td data-l=\"Session\"><b>${esc(stitle(s))}</b><div class=\"muted\">${esc(s.type || '')}${s.lieu ? ' · ' + esc(s.lieu) : ''}</div></td>\n      <td data-l=\"Inscriptions\"><div class=\"mini-meter\">${st.places ? `<i aria-hidden=\"true\"><b style=\"width:${Math.min(100, 100 * st.actifs / st.places)}%\"></b></i>` : ''}<span>${st.actifs}${st.places ? ' / ' + st.places : ''}</span></div></td><td data-l=\"Confirmées\">${st.c}${st.x ? `<div class=\"muted\">${st.x} annulée${st.x > 1 ? 's' : ''}</div>` : ''}</td><td data-l=\"Agenda\">${yes(s.publie) ? '<span class=\"badge b-ok\">Publié</span>' : '<span class=\"badge b-off\">Brouillon</span>'}</td></tr>`; }).join('')}</tbody></table></div>`\n      : `<div class=\"empty\">${sessFilter === 'avenir' ? 'Aucune session à venir. Créez votre prochaine formation ou votre prochain événement.' : 'Aucune session.'}</div>`;\n    $('#slist').querySelectorAll('tr[data-id]').forEach(tr => { const open = () => openSession(S.Sessions.find(s => s.id === tr.dataset.id)); tr.onclick = open; tr.onkeydown = e => { if (e.key === 'Enter') open(); }; });\n  };\n  document.querySelectorAll('[data-sf]').forEach(b => b.onclick = () => { sessFilter = b.dataset.sf; document.querySelectorAll('[data-sf]').forEach(x => x.setAttribute('aria-pressed', x === b)); draw(); });\n  $('#s-add').onclick = () => formDrawer({ title: 'Nouvelle session', fields: SESSION_FIELDS, row: { type: 'Formation', publie: 'Oui', places: 12 }, sheet: 'Sessions', saveLabel: 'Créer la session' });\n  draw();\n};\nfunction openSession(s, tab) {\n  if (!s) return;\n  tab = tab || 'details';\n  const st = sessionStats(s);\n  const STATUTS = ['Inscrit', 'Confirmé', 'Annulé', 'Présent', 'Absent'];\n  const link = `${D.agenda}?session=${encodeURIComponent(s.id)}`;\n  const insHtml = st.ins.length ? `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>Participant</th><th>Statut</th><th>Rappels</th></tr></thead><tbody>${st.ins.sort((a, b) => fullName(a).localeCompare(fullName(b))).map(i => `<tr><td data-l=\"Participant\"><b>${esc(fullName(i))}</b><div class=\"muted\">${esc(i.email)}${i.telephone ? ' · ' + esc(i.telephone) : ''} · ${esc(String(i.langue || 'fr').toUpperCase())}</div></td>\n      <td data-l=\"Statut\"><select class=\"select\" data-ins=\"${esc(i.id)}\" aria-label=\"Statut de ${esc(fullName(i))}\" style=\"min-height:38px;padding:6px 10px\">${STATUTS.map(x => `<option ${i.statut === x ? 'selected' : ''}>${x}</option>`).join('')}</select>${i.date_reponse ? `<div class=\"muted\">Réponse le ${esc(i.date_reponse)}</div>` : ''}</td>\n      <td data-l=\"Rappels\" class=\"muted\">${[i.rappel_J3 && 'J-3 envoyé', i.rappel_J1 && 'J-1 envoyé'].filter(Boolean).join(', ') || '–'}</td></tr>`).join('')}</tbody></table></div>` : '<p class=\"sub\">Aucune inscription pour le moment.</p>';\n  openDrawer({ title: stitle(s), sub: `${s.type || ''} · ${fdate(s.date)} · ${st.actifs} inscrit${st.actifs > 1 ? 's' : ''}${st.places ? ' sur ' + st.places : ''}`,\n    body: `<div class=\"tabs\" role=\"tablist\"><button role=\"tab\" type=\"button\" data-tab=\"details\" aria-selected=\"${tab === 'details'}\">Détails</button><button role=\"tab\" type=\"button\" data-tab=\"ins\" aria-selected=\"${tab === 'ins'}\">Inscrits (${st.ins.length})</button></div>\n      <div data-pane=\"details\" ${tab === 'details' ? '' : 'hidden'}><form id=\"dform\" novalidate>${fieldsHtml(SESSION_FIELDS, s)}</form>\n        <div class=\"help\">Lien d'inscription direct à partager : <code>${esc(link)}</code> <button class=\"btn btn-ghost btn-sm\" type=\"button\" id=\"cp-link\">Copier</button></div></div>\n      <div data-pane=\"ins\" ${tab === 'ins' ? '' : 'hidden'}>${insHtml}</div>`,\n    foot: `<button class=\"btn btn-danger\" type=\"button\" id=\"d-del\">Supprimer</button><div class=\"r\"><button class=\"btn btn-ghost\" type=\"button\" id=\"d-cancel\">Fermer</button><button class=\"btn btn-primary\" type=\"button\" id=\"d-save\">Enregistrer</button></div>`,\n    onOpen: () => {\n      const scope = $('#d-body'), ms = mountMulti(SESSION_FIELDS, s, scope);\n      scope.querySelectorAll('[data-tab]').forEach(b => b.onclick = () => { scope.querySelectorAll('[data-tab]').forEach(x => x.setAttribute('aria-selected', x === b)); scope.querySelectorAll('[data-pane]').forEach(p => p.hidden = p.dataset.pane !== b.dataset.tab); $('#d-save').style.visibility = b.dataset.tab === 'details' ? '' : 'hidden'; });\n      if (tab !== 'details') $('#d-save').style.visibility = 'hidden';\n      $('#cp-link').onclick = () => navigator.clipboard.writeText(link).then(() => toast('Lien copié'));\n      $('#d-cancel').onclick = closeDrawer;\n      $('#d-save').onclick = async () => { const v = readFields(SESSION_FIELDS, scope, ms); if (!v) return; try { await guard(() => save('Sessions', Object.assign({}, s, v))); closeDrawer(); refresh(); } catch (_) {} };\n      $('#d-del').onclick = async () => { if (!confirm(`Supprimer « ${stitle(s)} » ? Les ${st.ins.length} inscriptions resteront dans la base mais ne seront plus rattachées.`)) return; try { await guard(() => remove('Sessions', s.id, 'Session supprimée')); closeDrawer(); refresh(); } catch (_) {} };\n      scope.querySelectorAll('[data-ins]').forEach(sel => sel.onchange = async () => { const i = S.Inscriptions.find(x => x.id === sel.dataset.ins); try { await guard(() => save('Inscriptions', Object.assign({}, i, { statut: sel.value }), 'Statut mis à jour')); refresh(); } catch (_) { sel.value = i.statut; } });\n    } });\n}\n\n// ---------- Emails (templates) ----------\nconst TPL_GROUPS = [\n  ['Demandeurs', ['demande_recue', 'mise_en_relation_demandeur'], 'Envoyés dans les langues choisies par le demandeur.'],\n  ['Contacts', ['accord_contact', 'mise_en_relation_contact'], 'Envoyés dans la langue du contact (français ou anglais).'],\n  ['Participants', ['inscription_confirmee', 'rappel_j3', 'rappel_j1', 'annulation_participant'], 'Envoyés en français ou en anglais selon la langue de l’inscription.'],\n  ['Gestionnaire', ['gestionnaire_nouvelle_demande', 'gestionnaire_propositions', 'gestionnaire_reponse_contact', 'gestionnaire_nouvelle_inscription', 'gestionnaire_annulation'], 'Notifications envoyées à l’adresse du gestionnaire.']\n];\nconst TPL_NAMES = { demande_recue: 'Accusé de réception de la demande', mise_en_relation_demandeur: 'Coordonnées du contact', accord_contact: \"Demande d'accord au contact\", mise_en_relation_contact: 'Présentation du demandeur',\n  inscription_confirmee: \"Confirmation d'inscription\", rappel_j3: 'Rappel 3 jours avant', rappel_j1: 'Rappel la veille', annulation_participant: \"Confirmation d'annulation\",\n  gestionnaire_nouvelle_demande: 'Nouvelle demande', gestionnaire_propositions: 'Propositions à valider', gestionnaire_reponse_contact: \"Réponse d'un contact\", gestionnaire_nouvelle_inscription: 'Nouvelle inscription', gestionnaire_annulation: 'Annulation' };\nconst TPL_VARS = { demande_recue: ['prenom'], mise_en_relation_demandeur: ['prenom', 'contact_prenom', 'details_contact'], mise_en_relation_contact: ['prenom', 'demandeur_prenom', 'details_demandeur'],\n  accord_contact: ['prenom', 'demandeur_prenom', 'details_demandeur', 'lien_accepter', 'lien_refuser'], inscription_confirmee: ['prenom', 'titre', 'details_session', 'lien_annuler'],\n  rappel_j3: ['prenom', 'titre', 'details_session', 'lien_confirmer', 'lien_annuler'], rappel_j1: ['prenom', 'titre', 'details_session', 'lien_confirmer', 'lien_annuler'], annulation_participant: ['prenom', 'titre', 'lien_agenda'],\n  gestionnaire_nouvelle_demande: ['nom_complet', 'details_demandeur', 'lien_admin'], gestionnaire_propositions: ['nb', 'nb_demandes', 'liste_propositions', 'lien_admin'], gestionnaire_reponse_contact: ['contact_nom', 'reponse', 'demandeur_nom', 'suite', 'lien_admin'],\n  gestionnaire_nouvelle_inscription: ['nom_complet', 'email', 'titre', 'nb_inscrits', 'places_info', 'details_session', 'lien_admin'], gestionnaire_annulation: ['nom_complet', 'email', 'titre', 'moment', 'nb_inscrits', 'places_info', 'lien_admin'] };\nconst VAR_HELP = { prenom: 'Prénom du destinataire', contact_prenom: 'Prénom du contact', demandeur_prenom: 'Prénom du demandeur', titre: 'Titre de la session', nom_complet: 'Nom complet', email: 'Email', nb_inscrits: 'Nombre d’inscrits', places_info: '« sur 12 places »', moment: 'Moment de l’annulation', nb: 'Nombre de propositions', nb_demandes: 'Nombre de demandes', contact_nom: 'Nom du contact', demandeur_nom: 'Nom du demandeur', reponse: '« accepté » ou « refusé »', suite: 'Ce qui se passe ensuite' };\nlet tplSel = { cle: 'demande_recue', langue: 'fr' };\nfunction sampleVars(cle, langue) {\n  const s = S.Sessions[0] || { titre: 'Atelier CV', date: today, heure_debut: '14:00', lieu: 'Toulouse' };\n  const d = S.Demandeurs[0] || { prenom: 'Karim', nom: 'Exemple', metiers: '', langues: '' };\n  const c = S.Contacts[0] || { prenom: 'Julie', nom: 'Exemple', email: 'julie@example.com' };\n  const isContact = ['accord_contact', 'mise_en_relation_contact'].includes(cle), isDem = /demande_recue|mise_en_relation_demandeur/.test(cle);\n  const L = norm(langue) === 'en' ? 'en' : 'fr';\n  const propHtml = TW.box(P, `<b>${esc(fullName(d))}</b> → ${esc(fullName(c))} <span style=\"color:#4A6266\">(score 70)</span><br><span style=\"font-size:14px;color:#4A6266\">métier commun : ${esc(lib('metier', d.metiers) || 'Développeur·se')}</span><br>${TW.button(P, 'Valider', '#')}${TW.button(P, 'Refuser', '#', true)}`);\n  return { prenom: isContact ? c.prenom : isDem ? d.prenom : (S.Inscriptions[0] || {}).prenom || 'Amina', contact_prenom: c.prenom, demandeur_prenom: d.prenom, titre: TW.sessionTitle(s, L),\n    details_session: TW.detailsSession(P, s, L), details_contact: TW.detailsContact(P, c), details_demandeur: TW.detailsDemandeur(P, d, L, S.Listes, cle === 'mise_en_relation_contact' || cle.startsWith('gestionnaire')),\n    liste_propositions: propHtml, nom_complet: fullName(d), email: d.email || 'exemple@example.org', nb_inscrits: 8, places_info: 'sur 12 places', moment: 'en réponse au rappel J-1', nb: 2, nb_demandes: 1,\n    contact_nom: fullName(c), demandeur_nom: fullName(d), reponse: 'accepté', suite: 'Les coordonnées ont été envoyées automatiquement au demandeur.',\n    lien_accepter: '#', lien_refuser: '#', lien_annuler: '#', lien_confirmer: '#', lien_agenda: D.agenda, lien_admin: '#' };\n}\nVIEWS.emails = () => {\n  const all = S.Templates;\n  const known = new Set(TPL_GROUPS.flatMap(g => g[1]));\n  const extra = [...new Set(all.map(t => t.cle).filter(k => k && !known.has(k)))];\n  $('#view').innerHTML = `<div class=\"head\"><div><h1>Emails</h1><p>Modifiez le texte de chaque email. La mise en page et les couleurs s'appliquent automatiquement.</p></div></div>\n  <div class=\"tpl-pick field\"><label for=\"tpl-sel\">Email à modifier</label><select class=\"select\" id=\"tpl-sel\">${TPL_GROUPS.concat(extra.length ? [['Autres', extra, '']] : []).map(([g, keys]) => `<optgroup label=\"${esc(g)}\">${keys.map(k => `<option value=\"${esc(k)}\" ${tplSel.cle === k ? 'selected' : ''}>${esc(TPL_NAMES[k] || k)}</option>`).join('')}</optgroup>`).join('')}</select></div>\n  <div class=\"tpl-layout\"><nav class=\"tpl-list\" aria-label=\"Emails\">${TPL_GROUPS.concat(extra.length ? [['Autres', extra, '']] : []).map(([g, keys]) => `<h3>${g}</h3>${keys.map(k => { const langs = all.filter(t => t.cle === k).map(t => t.langue); return `<button type=\"button\" data-cle=\"${esc(k)}\" aria-current=\"${tplSel.cle === k}\"><b>${esc(TPL_NAMES[k] || k)}</b><span>${langs.length} langue${langs.length > 1 ? 's' : ''} : ${esc(langs.join(', ').toUpperCase())}</span></button>`; }).join('')}`).join('')}</nav>\n  <div id=\"tpl-ed\"></div></div>`;\n  document.querySelectorAll('[data-cle]').forEach(b => b.onclick = () => { tplSel = { cle: b.dataset.cle, langue: 'fr' }; VIEWS.emails(); });\n  $('#tpl-sel').onchange = e => { tplSel = { cle: e.target.value, langue: 'fr' }; VIEWS.emails(); };\n  drawEditor();\n};\nfunction drawEditor() {\n  const cle = tplSel.cle, rows = S.Templates.filter(t => t.cle === cle).sort((a, b) => (a.langue === 'fr' ? -1 : b.langue === 'fr' ? 1 : a.langue.localeCompare(b.langue)));\n  if (!rows.find(t => t.langue === tplSel.langue)) tplSel.langue = rows[0] ? rows[0].langue : 'fr';\n  const t = rows.find(x => x.langue === tplSel.langue) || { id: `${cle}|fr`, cle, langue: 'fr', sujet: '', contenu: '', description: '' };\n  const group = TPL_GROUPS.find(g => g[1].includes(cle));\n  const langName = c => (S.Listes.find(l => norm(l.type) === 'langue' && norm(l.code) === norm(c)) || {}).libelle_fr || c.toUpperCase();\n  const missing = listes('langue').filter(l => !rows.some(r => norm(r.langue) === norm(l.code)));\n  const multi = group && group[0] === 'Demandeurs';\n  const rtl = TW.RTL.includes(norm(t.langue));\n  $('#tpl-ed').innerHTML = `<div class=\"panel\" style=\"margin:0\"><h2>${esc(TPL_NAMES[cle] || cle)}</h2><p class=\"sub\">${esc(t.description || '')}${group && group[2] ? ' · ' + esc(group[2]) : ''}</p>\n    <div class=\"lang-pick field\"><label for=\"lg-sel\">Langue</label><select class=\"select\" id=\"lg-sel\">${rows.map(r => `<option value=\"${esc(r.langue)}\" ${r.langue === tplSel.langue ? 'selected' : ''}>${esc(langName(r.langue))}</option>`).join('')}</select></div>\n    <div class=\"tabs lang-tabs\" role=\"tablist\">${rows.map(r => `<button type=\"button\" role=\"tab\" data-lg=\"${esc(r.langue)}\" aria-selected=\"${r.langue === tplSel.langue}\">${esc(langName(r.langue))}</button>`).join('')}</div><div class=\"lang-add\">\n    ${(multi || ['fr', 'en'].some(c => !rows.some(r => r.langue === c))) && missing.length ? `<select class=\"select\" id=\"add-lg\" aria-label=\"Ajouter une langue\" style=\"width:auto;min-height:38px;padding:4px 10px\"><option value=\"\">+ Ajouter une langue</option>${missing.filter(l => multi || ['fr', 'en'].includes(l.code)).map(l => `<option value=\"${esc(l.code)}\">${esc(l.libelle_fr)}</option>`).join('')}</select>` : ''}</div>\n    <div class=\"tpl-edit\"><div>\n      <div class=\"help\">Cliquez sur une variable pour l'insérer. <code>**texte**</code> met en gras. Une ligne vide sépare deux paragraphes. Les boutons s'écrivent <code>[[Texte du bouton|lien_…]]</code>.</div>\n      <div class=\"field\"><label for=\"tp-s\">Objet de l'email</label><input class=\"input\" id=\"tp-s\" value=\"${esc(t.sujet)}\" dir=\"${rtl ? 'rtl' : 'ltr'}\"></div>\n      <div class=\"field\"><label for=\"tp-c\">Texte</label><div class=\"vars\">${(TPL_VARS[cle] || []).map(v => `<button type=\"button\" data-var=\"${v}\" title=\"${esc(VAR_HELP[v] || (v.startsWith('lien_') ? 'Bouton' : v.startsWith('details_') || v.startsWith('liste_') ? 'Encadré automatique' : v))}\">${v.startsWith('lien_') ? `[[…|${v}]]` : `{{${v}}}`}</button>`).join('')}</div>\n        <textarea class=\"textarea code\" id=\"tp-c\" dir=\"${rtl ? 'rtl' : 'ltr'}\">${esc(t.contenu)}</textarea></div>\n      <div style=\"display:flex;gap:10px;flex-wrap:wrap;justify-content:space-between\">${t.langue !== 'fr' && S.Templates.some(x => x.id === t.id) ? '<button class=\"btn btn-danger\" type=\"button\" id=\"tp-del\">Supprimer cette langue</button>' : '<span></span>'}<button class=\"btn btn-primary\" type=\"button\" id=\"tp-save\">Enregistrer</button></div>\n    </div>\n    <div class=\"preview\"><div class=\"pv-head\"><b>Aperçu</b> · <span id=\"pv-subj\"></span>${multi ? '<br><span class=\"muted\" style=\"font-size:13px\">Le demandeur reçoit un seul email avec une section par langue choisie.</span>' : ''}</div><iframe id=\"pv\" title=\"Aperçu de l'email\" sandbox=\"\"></iframe></div></div></div>`;\n  const s = $('#tp-s'), c = $('#tp-c');\n  const preview = () => {\n    const vars = sampleVars(cle, t.langue);\n    try { const em = TW.email([{ cle, langue: t.langue, sujet: s.value, contenu: c.value }], cle, [t.langue], vars, P); $('#pv').srcdoc = em.html; $('#pv-subj').textContent = em.sujet; }\n    catch (e) { $('#pv-subj').textContent = 'Texte vide'; $('#pv').srcdoc = ''; }\n  };\n  let tmr; s.oninput = c.oninput = () => { clearTimeout(tmr); tmr = setTimeout(preview, 250); };\n  preview();\n  document.querySelectorAll('[data-lg]').forEach(b => b.onclick = () => { tplSel.langue = b.dataset.lg; drawEditor(); });\n  $('#lg-sel').onchange = e => { tplSel.langue = e.target.value; drawEditor(); };\n  document.querySelectorAll('[data-var]').forEach(b => b.onclick = () => {\n    const v = b.dataset.var, ins = v.startsWith('lien_') ? `[[Texte du bouton|${v}]]` : (v.startsWith('details_') || v.startsWith('liste_')) ? `\\n\\n{{${v}}}\\n\\n` : `{{${v}}}`;\n    const a = c.selectionStart, z = c.selectionEnd; c.setRangeText(ins, a, z, 'end'); c.focus(); preview();\n  });\n  const add = $('#add-lg');\n  if (add) add.onchange = () => { if (!add.value) return; const base = rows.find(r => r.langue === 'fr') || rows[0] || t; const nt = { id: `${cle}|${add.value}`, cle, langue: add.value, description: base.description, sujet: base.sujet, contenu: base.contenu }; S.Templates.push(nt); tplSel.langue = add.value; drawEditor(); toast('Langue ajoutée : traduisez le texte puis enregistrez.'); };\n  $('#tp-save').onclick = async () => {\n    if (!c.value.trim()) { toast('Le texte ne peut pas être vide.', true); return; }\n    try { await guard(() => save('Templates', Object.assign({}, t, { id: `${cle}|${t.langue}`, sujet: s.value, contenu: c.value }), 'Email enregistré')); VIEWS.emails(); } catch (_) {}\n  };\n  const del = $('#tp-del');\n  if (del) del.onclick = async () => { if (!confirm(`Supprimer la version ${langName(t.langue)} de cet email ?`)) return; try { await guard(() => remove('Templates', t.id, 'Langue supprimée')); tplSel.langue = 'fr'; VIEWS.emails(); } catch (_) {} };\n}\n\n// ---------- Paramètres ----------\nVIEWS.parametres = () => {\n  const PF = [\n    ['nom_asso', 'Nom de l’association'], ['slogan', 'Slogan'], ['couleur_principale', 'Couleur principale', 'color'], ['couleur_encre', 'Couleur du texte', 'color'],\n    ['logo_url', 'Adresse du logo', 'url'], ['site_url', 'Site web', 'url'], ['email_gestionnaire', 'Email du gestionnaire', 'email'], ['signature', 'Signature des emails'],\n    ['pied_de_page', 'Pied de page des emails'], ['n8n_url', 'Adresse publique de n8n', 'url'], ['score_minimum', 'Score minimum du matching', 'number'], ['max_propositions', 'Propositions maximum par demande', 'number']\n  ];\n  const val = k => (S.Parametres.find(r => r.id === k) || {}).valeur ?? P[k] ?? '';\n  const desc = k => (S.Parametres.find(r => r.id === k) || {}).description || '';\n  const fields = PF.map(([k, l, ty]) => ({ k, label: l, type: ty || 'text', hint: desc(k) }));\n  const row = Object.fromEntries(PF.map(([k]) => [k, val(k)]));\n  $('#view').innerHTML = `<div class=\"head\"><div><h1>Paramètres</h1><p>Identité visuelle, adresses et listes du formulaire.</p></div></div>\n  <div class=\"panel\"><h2>Liens à partager</h2><p class=\"sub\">Publiez-les sur votre site, vos réseaux ou dans vos emails.</p><div class=\"links\">\n    ${[['Formulaire de demande', D.demande], ['Agenda et inscriptions', D.agenda], ['Formulaire en anglais', D.demande + '?lang=en'], ['Agenda en anglais', D.agenda + '?lang=en']].map(([l, u]) => `<div class=\"row\"><b>${l}</b><code>${esc(u)}</code><button class=\"btn btn-ghost btn-sm\" type=\"button\" data-copy=\"${esc(u)}\">Copier</button><a class=\"btn btn-ghost btn-sm\" href=\"${esc(u)}\" target=\"_blank\" rel=\"noopener\">Ouvrir</a></div>`).join('')}\n    <div class=\"row\"><b>Intégrer l'agenda à votre site</b><code>${esc(`<iframe src=\"${D.agenda}\" style=\"width:100%;height:900px;border:0\" title=\"Agenda Toulouse Way\"></iframe>`)}</code><button class=\"btn btn-ghost btn-sm\" type=\"button\" data-copy=\"${esc(`<iframe src=\"${D.agenda}\" style=\"width:100%;height:900px;border:0\" title=\"Agenda Toulouse Way\"></iframe>`)}\">Copier</button></div></div></div>\n  <div class=\"panel\"><h2>Identité et réglages</h2><p class=\"sub\">Appliqués aux emails, aux formulaires publics et à cet espace.</p><form id=\"pform\" novalidate>${fieldsHtml(fields, row)}</form><button class=\"btn btn-primary\" type=\"button\" id=\"p-save\">Enregistrer les paramètres</button></div>\n  <div class=\"cols\"><div class=\"panel\"><div class=\"head\" style=\"margin-bottom:10px\"><div><h2>Métiers</h2><p class=\"sub\" style=\"margin:0\">Proposés dans le formulaire de demande et pour les contacts.</p></div><button class=\"btn btn-ghost btn-sm\" type=\"button\" data-add=\"metier\">Ajouter</button></div><div id=\"l-metier\"></div></div>\n  <div class=\"panel\"><div class=\"head\" style=\"margin-bottom:10px\"><div><h2>Langues</h2><p class=\"sub\" style=\"margin:0\">Langues proposées aux demandeurs.</p></div><button class=\"btn btn-ghost btn-sm\" type=\"button\" data-add=\"langue\">Ajouter</button></div><div id=\"l-langue\"></div></div></div>`;\n  const scope = $('#pform'); mountMulti(fields, row, scope);\n  document.querySelectorAll('[data-copy]').forEach(b => b.onclick = () => navigator.clipboard.writeText(b.dataset.copy).then(() => toast('Copié')));\n  $('#p-save').onclick = async () => {\n    const v = readFields(fields, scope, {}); if (!v) return;\n    const changed = PF.filter(([k]) => String(v[k]) !== String(val(k)));\n    if (!changed.length) { toast('Aucune modification.'); return; }\n    try { for (const [k] of changed) await guard(() => save('Parametres', { id: k, valeur: String(v[k]), description: desc(k) }, false)); toast('Paramètres enregistrés'); VIEWS.parametres(); } catch (_) {}\n  };\n  for (const type of ['metier', 'langue']) {\n    const rows = listes(type);\n    $('#l-' + type).innerHTML = `<div class=\"tscroll\"><table class=\"t\"><thead><tr><th>${type === 'metier' ? 'Métier' : 'Langue'}</th><th>${type === 'metier' ? 'Secteur' : 'Nom natif'}</th></tr></thead><tbody>${rows.map(r => `<tr class=\"click\" tabindex=\"0\" data-lid=\"${esc(r.id)}\"><td data-l=\"Libellé\"><b>${esc(r.libelle_fr)}</b><div class=\"muted\">${esc(r.libelle_en)} · code ${esc(r.code)}</div></td><td data-l=\"${type === 'metier' ? 'Secteur' : 'Nom natif'}\">${esc(type === 'metier' ? String(r.groupe || '').split('|')[0] : r.libelle_natif)}</td></tr>`).join('')}</tbody></table></div>`;\n  }\n  const LF = type => [{ k: 'libelle_fr', label: 'Libellé en français', req: true }, { k: 'libelle_en', label: 'Libellé en anglais', req: true },\n    { k: 'code', label: 'Code', req: true, hint: type === 'langue' ? 'Code ISO à 2 lettres (ex. es). Il relie la langue aux emails traduits.' : 'Identifiant court sans espace (ex. dev-web). Ne le changez plus ensuite.' },\n    type === 'metier' ? { k: 'groupe', label: 'Secteur', hint: 'Format : « Secteur en français | Sector in English »' } : { k: 'libelle_natif', label: 'Nom dans la langue elle-même' },\n    { k: 'ordre', label: \"Ordre d'affichage\", type: 'number' }];\n  const editL = (type, r) => formDrawer({ title: r ? r.libelle_fr : (type === 'metier' ? 'Nouveau métier' : 'Nouvelle langue'), fields: LF(type), row: r || { type, ordre: listes(type).length + 1 }, sheet: 'Listes', del: !!r,\n    delMsg: 'Supprimer cet élément de la liste ? Les demandes existantes garderont le code.', onSaved: () => {} });\n  document.querySelectorAll('[data-add]').forEach(b => b.onclick = () => editL(b.dataset.add, null));\n  document.querySelectorAll('[data-lid]').forEach(tr => { const r = S.Listes.find(x => x.id === tr.dataset.lid); const open = () => editL(norm(r.type), r); tr.onclick = open; tr.onkeydown = e => { if (e.key === 'Enter') open(); }; });\n};\n</script>\n</body>\n</html>\n";
// Construit l'espace gestion (les données arrivent ensuite par l'API protégée)
const P = TW.params($('Paramètres (gestion)').all().map(i => i.json));
const data = {
  P: { nom_asso: P.nom_asso, slogan: P.slogan, logo_url: P.logo_url, site_url: P.site_url, couleur_principale: P.couleur_principale, couleur_encre: P.couleur_encre },
  api: 'tw-api', mer: 'tw-decision',
  demande: P.n8n_url && !/VOTRE-INSTANCE/.test(P.n8n_url) ? TW.link(P, 'tw-demande') : 'tw-demande',
  agenda: P.n8n_url && !/VOTRE-INSTANCE/.test(P.n8n_url) ? TW.link(P, 'tw-agenda') : 'tw-agenda'
};
return [{ json: { html: TPL.split('/*__DATA__*/null').join(JSON.stringify(data).replace(/</g, '\\u003c')) } }];
